use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{anyhow, bail, Context, Result};
use serde::{Deserialize, Serialize};

pub const CONFIG_FILE_NAME: &str = "config.toml";
pub const THEMES_FILE_NAME: &str = "themes.toml";
pub const APP_DIR_NAME: &str = "tui-journal";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum BackendType {
    Json,
    #[default]
    Sqlite,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum DatumVisibility {
    #[default]
    Show,
    Hide,
    EmptyLine,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct ExportSettings {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub default_path: Option<PathBuf>,
    pub show_confirmation: bool,
}

impl Default for ExportSettings {
    fn default() -> Self {
        Self {
            default_path: None,
            show_confirmation: true,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct ExternalEditorSettings {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub command: Option<String>,
    pub auto_save: bool,
    pub temp_file_extension: String,
}

impl Default for ExternalEditorSettings {
    fn default() -> Self {
        Self {
            command: None,
            auto_save: false,
            temp_file_extension: "txt".to_string(),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct JsonBackendSettings {
    pub file_path: PathBuf,
}

impl Default for JsonBackendSettings {
    fn default() -> Self {
        Self {
            file_path: default_data_dir().join("entries.json"),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct SqliteBackendSettings {
    pub file_path: PathBuf,
}

impl Default for SqliteBackendSettings {
    fn default() -> Self {
        Self {
            file_path: default_data_dir().join("entries.db"),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct Settings {
    pub backend_type: BackendType,
    pub scroll_per_page: usize,
    pub sync_os_clipboard: bool,
    pub history_limit: usize,
    pub colored_tags: bool,
    pub datum_visibility: DatumVisibility,
    pub app_state_dir: PathBuf,
    pub export: ExportSettings,
    pub external_editor: ExternalEditorSettings,
    pub json_backend: JsonBackendSettings,
    pub sqlite_backend: SqliteBackendSettings,
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            backend_type: BackendType::default(),
            scroll_per_page: 5,
            sync_os_clipboard: false,
            history_limit: 10,
            colored_tags: true,
            datum_visibility: DatumVisibility::default(),
            app_state_dir: default_state_dir(),
            export: ExportSettings::default(),
            external_editor: ExternalEditorSettings::default(),
            json_backend: JsonBackendSettings::default(),
            sqlite_backend: SqliteBackendSettings::default(),
        }
    }
}

fn default_data_dir() -> PathBuf {
    dirs::document_dir()
        .or_else(dirs::home_dir)
        .unwrap_or_default()
        .join(APP_DIR_NAME)
}

fn default_state_dir() -> PathBuf {
    dirs::state_dir()
        .or_else(dirs::data_local_dir)
        .unwrap_or_default()
        .join(APP_DIR_NAME)
}

impl Settings {
    pub fn default_config_dir() -> Option<PathBuf> {
        dirs::config_dir().map(|p| p.join(APP_DIR_NAME))
    }

    /// Resolves the configuration file path from the optional custom path.
    /// The custom path can be a directory (containing config.toml) or a file.
    pub fn resolve_config_file(custom: Option<&Path>) -> Result<PathBuf> {
        match custom {
            Some(path) => {
                if !path.exists() {
                    bail!(
                        "Provided custom directory doesn't exit. Path: {}",
                        path.display()
                    );
                }
                if path.is_dir() {
                    Ok(path.join(CONFIG_FILE_NAME))
                } else {
                    Ok(path.to_path_buf())
                }
            }
            None => {
                let dir = Self::default_config_dir()
                    .ok_or_else(|| anyhow!("Config directory couldn't be found"))?;
                Ok(dir.join(CONFIG_FILE_NAME))
            }
        }
    }

    /// Resolves the themes directory. When the custom path is a file, the
    /// default directory is used instead.
    pub fn resolve_themes_file(custom: Option<&Path>) -> Result<PathBuf> {
        let dir = match custom {
            Some(path) if path.is_dir() => path.to_path_buf(),
            Some(_) => {
                log::warn!(
                    "Custom config directory is ignored in themese because it's not a directory"
                );
                eprintln!(
                    "INFO: Custom config directory is ignored in themese because it's not a directory."
                );
                Self::default_config_dir()
                    .ok_or_else(|| anyhow!("Config directory couldn't be found"))?
            }
            None => Self::default_config_dir()
                .ok_or_else(|| anyhow!("Config directory couldn't be found"))?,
        };
        Ok(dir.join(THEMES_FILE_NAME))
    }

    pub fn load(custom: Option<&Path>) -> Result<Self> {
        let file = Self::resolve_config_file(custom)?;
        if !file.exists() {
            return Ok(Self::default());
        }
        let text = fs::read_to_string(&file).with_context(|| {
            format!("Failed to read configuration file. Path: {}", file.display())
        })?;
        let settings: Settings = toml::from_str(&text)
            .map_err(|err| anyhow!("Failed to read configuration file. Error infos: {err}"))?;
        Ok(settings)
    }

    pub fn to_toml(&self) -> Result<String> {
        toml::to_string(self).context("Failed to serialize settings")
    }
}
EOF
echo ok"}

