fn default_data_dir() -> PathBuf {
    dirs::document_dir()
        .or_else(dirs::home_dir)
        .unwrap_or_default()
        .join(APP_DIR_NAME)
}

fn default_state_dir() -> PathBuf {
    dirs::state_dir()
        .or_else(dirs::data_local_dir)
        .unwrap_or_default()
        .join(APP_DIR_NAME)
}

impl Settings {
    pub fn default_config_dir() -> Option<PathBuf> {
        dirs::config_dir().map(|p| p.join(APP_DIR_NAME))
    }

    /// Resolves the configuration file path from the optional custom path.
    /// The custom path can be a directory (containing config.toml) or a file.
    pub fn resolve_config_file(custom: Option<&Path>) -> Result<PathBuf> {
        match custom {
            Some(path) => {
                if !path.exists() {
                    bail!(
                        "Provided custom directory doesn't exit. Path: {}",
                        path.display()
                    );
                }
                if path.is_dir() {
                    Ok(path.join(CONFIG_FILE_NAME))
                } else {
                    Ok(path.to_path_buf())
                }
            }
            None => {
                let dir = Self::default_config_dir()
                    .ok_or_else(|| anyhow!("Config directory couldn't be found"))?;
                Ok(dir.join(CONFIG_FILE_NAME))
            }
        }
    }

    /// Resolves the themes directory. When the custom path is a file, the
    /// default directory is used instead.
    pub fn resolve_themes_file(custom: Option<&Path>) -> Result<PathBuf> {
        let dir = match custom {
            Some(path) if path.is_dir() => path.to_path_buf(),
            Some(_) => {
                log::warn!(
                    "Custom config directory is ignored in themese because it's not a directory"
                );
                eprintln!(
                    "INFO: Custom config directory is ignored in themese because it's not a directory."
                );
                Self::default_config_dir()
                    .ok_or_else(|| anyhow!("Config directory couldn't be found"))?
            }
            None => Self::default_config_dir()
                .ok_or_else(|| anyhow!("Config directory couldn't be found"))?,
        };
        Ok(dir.join(THEMES_FILE_NAME))
    }

    pub fn load(custom: Option<&Path>) -> Result<Self> {
        let file = Self::resolve_config_file(custom)?;
        if !file.exists() {
            return Ok(Self::default());
        }
        let text = fs::read_to_string(&file).with_context(|| {
            format!("Failed to read configuration file. Path: {}", file.display())
        })?;
        let settings: Settings = toml::from_str(&text)
            .map_err(|err| anyhow!("Failed to read configuration file. Error infos: {err}"))?;
        Ok(settings)
    }

    pub fn to_toml(&self) -> Result<String> {
        toml::to_string(self).context("Failed to serialize settings")
    }
}
