use std::fs::{self, File, OpenOptions};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

use anyhow::{Context, Result};
use log::{Level, LevelFilter, Log, Metadata, Record};

pub fn default_log_file() -> Option<PathBuf> {
    dirs::cache_dir().map(|p| p.join(crate::settings::APP_DIR_NAME).join("tui-journal.log"))
}

struct FileLogger {
    file: Mutex<File>,
    level: LevelFilter,
}

fn thread_id_number() -> u64 {
    // Approximate the numeric thread id similar to the one used by log formatters.
    let id = std::thread::current().id();
    let s = format!("{id:?}");
    s.trim_start_matches("ThreadId(")
        .trim_end_matches(')')
        .parse()
        .unwrap_or(0)
}

impl Log for FileLogger {
    fn enabled(&self, metadata: &Metadata) -> bool {
        metadata.level() <= self.level
    }

    fn log(&self, record: &Record) {
        if !self.enabled(record.metadata()) {
            return;
        }
        let time = chrono::Local::now().format("%H:%M:%S");
        let level = record.level();
        let line = match level {
            Level::Trace => format!(
                "{time} [{level}] ({}) {}: [{}:{}] {}\n",
                thread_id_number(),
                record.target(),
                record.file().unwrap_or("<unknown>"),
                record.line().unwrap_or(0),
                record.args()
            ),
            Level::Debug => format!(
                "{time} [{level}] ({}) {}: {}\n",
                thread_id_number(),
                record.target(),
                record.args()
            ),
            _ => format!("{time} [{level}] {}\n", record.args()),
        };
        if let Ok(mut f) = self.file.lock() {
            let _ = f.write_all(line.as_bytes());
            let _ = f.flush();
        }
    }

    fn flush(&self) {
        if let Ok(mut f) = self.file.lock() {
            let _ = f.flush();
        }
    }
}

pub fn init(verbose: u8, log_file: Option<&Path>) -> Result<()> {
    let level = match verbose {
        0 => LevelFilter::Warn,
        1 => LevelFilter::Info,
        2 => LevelFilter::Debug,
        _ => LevelFilter::Trace,
    };

    let path = match log_file {
        Some(p) => p.to_path_buf(),
        None => default_log_file().context("Log directory couldn't be found")?,
    };

    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("Failed to create log directory: {}", parent.display()))?;
    }

    let file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
        .with_context(|| format!("Failed to open log file: {}", path.display()))?;

    let logger = FileLogger {
        file: Mutex::new(file),
        level,
    };

    log::set_boxed_logger(Box::new(logger)).context("Failed to set logger")?;
    log::set_max_level(level);

    log::trace!("Log initialized with level: {level}");

    Ok(())
}
