use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{anyhow, Context, Result};

use super::{DataProvider, Entry, EntryDraft};

pub struct JsonDataProvider {
    file_path: PathBuf,
}

impl JsonDataProvider {
    pub fn new(file_path: PathBuf) -> Self {
        Self { file_path }
    }

    fn read_entries(&self) -> Result<Vec<Entry>> {
        if !self.file_path.exists() {
            return Ok(Vec::new());
        }
        let text = fs::read_to_string(&self.file_path).with_context(|| {
            format!(
                "Failed to read entries file: {}",
                self.file_path.display()
            )
        })?;
        if text.trim().is_empty() {
            return Ok(Vec::new());
        }
        match serde_json::from_str::<Vec<Entry>>(&text) {
            Ok(entries) => Ok(entries),
            Err(err) => {
                log::error!(
                    "Failed to parse entries json file {}: {err}",
                    self.file_path.display()
                );
                Ok(Vec::new())
            }
        }
    }

    fn write_entries(&self, entries: &[Entry]) -> Result<()> {
        ensure_parent_dir(&self.file_path)?;
        let text = serde_json::to_string(entries).context("Failed to serialize entries")?;
        fs::write(&self.file_path, text).with_context(|| {
            format!(
                "Failed to write entries file: {}",
                self.file_path.display()
            )
        })?;
        Ok(())
    }
}

pub fn ensure_parent_dir(path: &Path) -> Result<()> {
    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() && !parent.exists() {
            fs::create_dir_all(parent)
                .with_context(|| format!("Failed to create directory: {}", parent.display()))?;
        }
    }
    Ok(())
}

impl DataProvider for JsonDataProvider {
    fn load_all_entries(&self) -> Result<Vec<Entry>> {
        self.read_entries()
    }

    fn add_entry(&self, draft: EntryDraft) -> Result<Entry> {
        let mut entries = self.read_entries()?;
        let id = entries.iter().map(|e| e.id + 1).max().unwrap_or(0);
        let entry = Entry::new(
            id,
            draft.date,
            draft.title,
            draft.content,
            draft.tags,
            draft.priority,
        );
        entries.push(entry.clone());
        self.write_entries(&entries)?;
        Ok(entry)
    }

    fn remove_entry(&self, entry_id: u32) -> Result<()> {
        let mut entries = self.read_entries()?;
        entries.retain(|e| e.id != entry_id);
        self.write_entries(&entries)
    }

    fn update_entry(&self, entry: Entry) -> Result<Entry> {
        let mut entries = self.read_entries()?;
        let existing = entries
            .iter_mut()
            .find(|e| e.id == entry.id)
            .ok_or_else(|| anyhow!("Entry with id {} not found", entry.id))?;
        *existing = entry.clone();
        self.write_entries(&entries)?;
        Ok(entry)
    }

    fn remove_entries(&self, ids: &[u32]) -> Result<()> {
        let mut entries = self.read_entries()?;
        entries.retain(|e| !ids.contains(&e.id));
        self.write_entries(&entries)
    }

    fn import_entries(&self, drafts: Vec<EntryDraft>) -> Result<()> {
        let mut entries = self.read_entries()?;
        let mut next_id = entries.iter().map(|e| e.id + 1).max().unwrap_or(0);
        for draft in drafts {
            entries.push(Entry::new(
                next_id,
                draft.date,
                draft.title,
                draft.content,
                draft.tags,
                draft.priority,
            ));
            next_id += 1;
        }
        self.write_entries(&entries)
    }

    fn assign_priority_to_entries(&self, priority: u32) -> Result<()> {
        let mut entries = self.read_entries()?;
        for entry in entries.iter_mut() {
            if entry.priority.is_none() {
                entry.priority = Some(priority);
            }
        }
        self.write_entries(&entries)
    }
}
