    fn remove_entry(&self, entry_id: u32) -> Result<()> {
        let mut entries = self.read_entries()?;
        entries.retain(|e| e.id != entry_id);
        self.write_entries(&entries)
    }

    fn update_entry(&self, entry: Entry) -> Result<Entry> {
        let mut entries = self.read_entries()?;
        let existing = entries
            .iter_mut()
            .find(|e| e.id == entry.id)
            .ok_or_else(|| anyhow!("Entry with id {} not found", entry.id))?;
        *existing = entry.clone();
        self.write_entries(&entries)?;
        Ok(entry)
    }

    fn remove_entries(&self, ids: &[u32]) -> Result<()> {
        let mut entries = self.read_entries()?;
        entries.retain(|e| !ids.contains(&e.id));
        self.write_entries(&entries)
    }

    fn import_entries(&self, drafts: Vec<EntryDraft>) -> Result<()> {
        let mut entries = self.read_entries()?;
        let mut next_id = entries.iter().map(|e| e.id + 1).max().unwrap_or(0);
        for draft in drafts {
            entries.push(Entry::new(
                next_id,
                draft.date,
                draft.title,
                draft.content,
                draft.tags,
                draft.priority,
            ));
            next_id += 1;
        }
        self.write_entries(&entries)
    }

    fn assign_priority_to_entries(&self, priority: u32) -> Result<()> {
        let mut entries = self.read_entries()?;
        for entry in entries.iter_mut() {
            if entry.priority.is_none() {
                entry.priority = Some(priority);
            }
        }
        self.write_entries(&entries)
    }
}
