fn hex_to_bytes(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .filter_map(|i| u8::from_str_radix(&hex[i..i + 2], 16).ok())
        .collect()
}

pub struct SqliteDataProvider {
    file_path: PathBuf,
}

impl SqliteDataProvider {
    pub fn new(file_path: PathBuf) -> Result<Self> {
        let provider = Self { file_path };
        provider.init()?;
        Ok(provider)
    }

    fn init(&self) -> Result<()> {
        super::json::ensure_parent_dir(&self.file_path)?;
        let conn = self.connect()?;
        conn.exec(
            "CREATE TABLE IF NOT EXISTS _sqlx_migrations (\n    version BIGINT PRIMARY KEY,\n    description TEXT NOT NULL,\n    installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    success BOOLEAN NOT NULL,\n    checksum BLOB NOT NULL,\n    execution_time BIGINT NOT NULL\n);",
        )?;

        // Collect applied versions.
        let mut applied = Vec::new();
        {
            let mut stmt =
                conn.prepare("SELECT version FROM _sqlx_migrations ORDER BY version")?;
            while let StepResult::Row = stmt.step()? {
                applied.push(stmt.column_i64(0));
            }
        }

        for migration in MIGRATIONS {
            if applied.contains(&migration.version) {
                continue;
            }
            let start = std::time::Instant::now();
            conn.exec(migration.sql)?;
            let elapsed = start.elapsed().as_nanos() as i64;
            let checksum = hex_to_bytes(migration.checksum);
            conn.execute(
                "INSERT INTO _sqlx_migrations ( version, description, success, checksum, execution_time ) VALUES ( ?1, ?2, TRUE, ?3, ?4 )",
                &[
                    Value::Int(migration.version),
                    Value::Text(migration.description),
                    Value::Blob(&checksum),
                    Value::Int(elapsed),
                ],
            )?;
        }
        Ok(())
    }

    fn connect(&self) -> Result<Connection> {
        let conn = Connection::open(&self.file_path)?;
        conn.exec("PRAGMA journal_mode = OFF; PRAGMA foreign_keys = ON; PRAGMA synchronous = OFF;")?;
        Ok(conn)
    }

    fn load_tags(conn: &Connection, entry_id: i64) -> Result<Vec<String>> {
        let mut stmt = conn.prepare("SELECT tag FROM tags WHERE entry_id = ?1 ORDER BY rowid")?;
        stmt.bind_all(&[Value::Int(entry_id)])?;
        let mut tags = Vec::new();
        while let StepResult::Row = stmt.step()? {
            tags.push(stmt.column_text(0));
        }
        Ok(tags)
    }

    fn insert_tags(conn: &Connection, entry_id: i64, tags: &[String]) -> Result<()> {
        for tag in tags {
            conn.execute(
                "INSERT OR IGNORE INTO tags (entry_id, tag) VALUES (?1, ?2)",
                &[Value::Int(entry_id), Value::Text(tag)],
            )?;
        }
        Ok(())
    }

    fn insert_entry(conn: &Connection, draft: &EntryDraft) -> Result<Entry> {
        let date = format_date(&draft.date);
        let priority = match draft.priority {
            Some(p) => Value::Int(p as i64),
            None => Value::Null,
        };
        conn.execute(
            "INSERT INTO entries (title, date, content, priority) VALUES (?1, ?2, ?3, ?4)",
            &[
                Value::Text(&draft.title),
                Value::Text(&date),
                Value::Text(&draft.content),
                priority,
            ],
        )?;
        let id = conn.last_insert_rowid();
        Self::insert_tags(conn, id, &draft.tags)?;
        Ok(Entry::new(
            id as u32,
            draft.date,
            draft.title.clone(),
            draft.content.clone(),
            draft.tags.clone(),
            draft.priority,
        ))
    }
}

pub fn format_date(date: &DateTime<Utc>) -> String {
    date.to_rfc3339_opts(chrono::SecondsFormat::AutoSi, false)
}

pub fn parse_date(text: &str) -> Result<DateTime<Utc>> {
    if let Ok(dt) = DateTime::parse_from_rfc3339(text) {
        return Ok(dt.with_timezone(&Utc));
    }
    for fmt in [
        "%Y-%m-%d %H:%M:%S%.f%:z",
        "%Y-%m-%dT%H:%M:%S%.f",
        "%Y-%m-%d %H:%M:%S%.f",
        "%Y-%m-%d %H:%M:%S",
    ] {
        if let Ok(dt) = DateTime::parse_from_str(text, fmt) {
            return Ok(dt.with_timezone(&Utc));
        }
        if let Ok(ndt) = NaiveDateTime::parse_from_str(text, fmt) {
            return Ok(ndt.and_utc());
        }
    }
    if let Ok(d) = NaiveDate::parse_from_str(text, "%Y-%m-%d") {
        return Ok(d.and_hms_opt(0, 0, 0).unwrap().and_utc());
    }
    Err(anyhow!("Invalid date value in database: {text}"))
}

impl DataProvider for SqliteDataProvider {
    fn load_all_entries(&self) -> Result<Vec<Entry>> {
        let conn = self.connect()?;
        let mut entries = Vec::new();
        {
            let mut stmt = conn.prepare(
                "SELECT id, title, date, content, priority FROM entries ORDER BY date DESC",
            )?;
            while let StepResult::Row = stmt.step()? {
                let id = stmt.column_i64(0);
                let title = stmt.column_text(1);
                let date = parse_date(&stmt.column_text(2))?;
                let content = if stmt.column_is_null(3) {
                    String::new()
                } else {
                    stmt.column_text(3)
                };
                let priority = if stmt.column_is_null(4) {
                    None
                } else {
                    Some(stmt.column_i64(4) as u32)
                };
                entries.push(Entry::new(id as u32, date, title, content, Vec::new(), priority));
            }
        }
        for entry in entries.iter_mut() {
            entry.tags = Self::load_tags(&conn, entry.id as i64)?;
        }
        Ok(entries)
    }

    fn add_entry(&self, draft: EntryDraft) -> Result<Entry> {
        let conn = self.connect()?;
        Self::insert_entry(&conn, &draft)
    }

    fn remove_entry(&self, entry_id: u32) -> Result<()> {
        let conn = self.connect()?;
        conn.execute(
            "DELETE FROM tags WHERE entry_id = ?1",
            &[Value::Int(entry_id as i64)],
        )?;
        conn.execute(
            "DELETE FROM entries WHERE id = ?1",
            &[Value::Int(entry_id as i64)],
        )?;
        Ok(())
    }

    fn update_entry(&self, entry: Entry) -> Result<Entry> {
        let conn = self.connect()?;
        let date = format_date(&entry.date);
        let priority = match entry.priority {
            Some(p) => Value::Int(p as i64),
            None => Value::Null,
        };
        conn.execute(
            "UPDATE entries SET title = ?1, date = ?2, content = ?3, priority = ?4 WHERE id = ?5",
            &[
                Value::Text(&entry.title),
                Value::Text(&date),
                Value::Text(&entry.content),
                priority,
                Value::Int(entry.id as i64),
            ],
        )?;
        conn.execute(
            "DELETE FROM tags WHERE entry_id = ?1",
            &[Value::Int(entry.id as i64)],
        )?;
        Self::insert_tags(&conn, entry.id as i64, &entry.tags)?;
        Ok(entry)
    }

    fn import_entries(&self, entries: Vec<EntryDraft>) -> Result<()> {
        let conn = self.connect()?;
        conn.exec("BEGIN")?;
        for draft in entries.iter() {
            if let Err(err) = Self::insert_entry(&conn, draft) {
                let _ = conn.exec("ROLLBACK");
                return Err(err);
            }
        }
        conn.exec("COMMIT")?;
        Ok(())
    }

    fn assign_priority_to_entries(&self, priority: u32) -> Result<()> {
        let conn = self.connect()?;
        conn.execute(
            "UPDATE entries SET priority = ?1 WHERE priority IS NULL",
            &[Value::Int(priority as i64)],
        )?;
        Ok(())
    }
}
