    fn exec(&self, sql: &str) -> Result<()> {
        let c_sql = CString::new(sql).context("Invalid SQL text")?;
        let mut err: *mut c_char = ptr::null_mut();
        let rc = unsafe {
            sqlite3_exec(
                self.db,
                c_sql.as_ptr(),
                ptr::null(),
                ptr::null_mut(),
                &mut err,
            )
        };
        if rc != SQLITE_OK {
            let msg = if err.is_null() {
                self.last_error()
            } else {
                let s = unsafe { CStr::from_ptr(err) }.to_string_lossy().into_owned();
                unsafe { sqlite3_free(err as *mut c_void) };
                s
            };
            bail!("error returned from database: {msg}");
        }
        Ok(())
    }

    fn prepare(&self, sql: &str) -> Result<Statement<'_>> {
        let c_sql = CString::new(sql).context("Invalid SQL text")?;
        let mut stmt: *mut sqlite3_stmt = ptr::null_mut();
        let rc = unsafe {
            sqlite3_prepare_v2(self.db, c_sql.as_ptr(), -1, &mut stmt, ptr::null_mut())
        };
        if rc != SQLITE_OK {
            bail!("error returned from database: {}", self.last_error());
        }
        Ok(Statement { conn: self, stmt })
    }

    fn execute(&self, sql: &str, params: &[Value]) -> Result<()> {
        let mut stmt = self.prepare(sql)?;
        stmt.bind_all(params)?;
        loop {
            match stmt.step()? {
                StepResult::Row => continue,
                StepResult::Done => break,
            }
        }
        Ok(())
    }

    fn last_insert_rowid(&self) -> i64 {
        unsafe { sqlite3_last_insert_rowid(self.db) }
    }
}

enum StepResult {
    Row,
    Done,
}

impl<'c> Statement<'c> {
    fn bind_all(&mut self, params: &[Value]) -> Result<()> {
        for (i, p) in params.iter().enumerate() {
            let idx = (i + 1) as c_int;
            let rc = unsafe {
                match p {
                    Value::Int(v) => sqlite3_bind_int64(self.stmt, idx, *v),
                    Value::Null => sqlite3_bind_null(self.stmt, idx),
                    Value::Text(s) => sqlite3_bind_text(
                        self.stmt,
                        idx,
                        s.as_ptr() as *const c_char,
                        s.len() as c_int,
                        SQLITE_TRANSIENT,
                    ),
                    Value::Blob(b) => sqlite3_bind_blob(
                        self.stmt,
                        idx,
                        b.as_ptr() as *const c_void,
                        b.len() as c_int,
                        SQLITE_TRANSIENT,
                    ),
                }
            };
            if rc != SQLITE_OK {
                bail!("error returned from database: {}", self.conn.last_error());
            }
        }
        Ok(())
    }

    fn step(&mut self) -> Result<StepResult> {
        let rc = unsafe { sqlite3_step(self.stmt) };
        match rc {
            SQLITE_ROW => Ok(StepResult::Row),
            SQLITE_DONE => Ok(StepResult::Done),
            _ => bail!("error returned from database: {}", self.conn.last_error()),
        }
    }

    fn column_is_null(&self, col: c_int) -> bool {
        unsafe { sqlite3_column_type(self.stmt, col) == SQLITE_NULL }
    }

    fn column_i64(&self, col: c_int) -> i64 {
        unsafe { sqlite3_column_int64(self.stmt, col) }
    }

    fn column_text(&self, col: c_int) -> String {
        unsafe {
            let p = sqlite3_column_text(self.stmt, col);
            if p.is_null() {
                return String::new();
            }
            let n = sqlite3_column_bytes(self.stmt, col) as usize;
            let bytes = std::slice::from_raw_parts(p, n);
            String::from_utf8_lossy(bytes).into_owned()
        }
    }
}

