#[derive(Clone, Copy, PartialEq, Eq)]
enum CharKind {
    Space,
    Punct,
    Other,
}

impl CharKind {
    fn new(c: char) -> Self {
        if c.is_whitespace() {
            Self::Space
        } else if c.is_ascii_punctuation() {
            Self::Punct
        } else {
            Self::Other
        }
    }
}

fn find_word_start_forward(line: &str, start_col: usize) -> Option<usize> {
    let mut it = line.chars().enumerate().skip(start_col);
    let mut prev = CharKind::new(it.next()?.1);
    for (col, c) in it {
        let cur = CharKind::new(c);
        if cur != CharKind::Space && prev != cur {
            return Some(col);
        }
        prev = cur;
    }
    None
}

fn find_word_exclusive_end_forward(line: &str, start_col: usize) -> Option<usize> {
    let mut it = line.chars().enumerate().skip(start_col);
    let mut prev = CharKind::new(it.next()?.1);
    for (col, c) in it {
        let cur = CharKind::new(c);
        if prev != CharKind::Space && cur != prev {
            return Some(col);
        }
        prev = cur;
    }
    None
}

fn find_word_inclusive_end_forward(line: &str, start_col: usize) -> Option<usize> {
    let mut it = line.chars().enumerate().skip(start_col);
    let (mut last_col, c) = it.next()?;
    let mut prev = CharKind::new(c);
    for (col, c) in it {
        let cur = CharKind::new(c);
        if prev != CharKind::Space && cur != prev {
            return Some(col - 1);
        }
        prev = cur;
        last_col = col;
    }
    if prev != CharKind::Space {
        Some(last_col)
    } else {
        None
    }
}

fn find_word_start_backward(line: &str, start_col: usize) -> usize {
    let idx = line
        .char_indices()
        .nth(start_col)
        .map(|(i, _)| i)
        .unwrap_or(line.len());
    let mut it = line[..idx].chars().rev().enumerate();
    let mut cur = match it.next() {
        Some((_, c)) => CharKind::new(c),
        None => return 0,
    };
    for (i, c) in it {
        let next = CharKind::new(c);
        if cur != CharKind::Space && next != cur {
            return start_col - i;
        }
        cur = next;
    }
    0
}

#[derive(Clone, Debug)]
enum EditKind {
    InsertChar(char, usize),
    DeleteChar(char, usize),
    InsertNewline(usize),
    DeleteNewline(usize),
    InsertStr(String, usize),
    DeleteStr(String, usize),
    InsertChunk(Vec<String>, usize, usize),
    DeleteChunk(Vec<String>, usize, usize),
}

#[derive(Clone, Debug)]
struct Edit {
    kind: EditKind,
    cursor_before: (usize, usize),
    cursor_after: (usize, usize),
}

struct History {
    index: usize,
    max_items: usize,
    edits: std::collections::VecDeque<Edit>,
}

impl History {
    fn new(max_items: usize) -> Self {
        Self {
            index: 0,
            max_items,
            edits: std::collections::VecDeque::new(),
        }
    }

    fn push(&mut self, edit: Edit) {
        if self.max_items == 0 {
            return;
        }
        if self.edits.len() == self.max_items {
            self.edits.pop_front();
            self.index = self.index.saturating_sub(1);
        }
        if self.index < self.edits.len() {
            self.edits.truncate(self.index);
        }
        self.index += 1;
        self.edits.push_back(edit);
    }

    fn clear(&mut self) {
        self.index = 0;
        self.edits.clear();
    }
}

fn apply_edit(lines: &mut Vec<String>, kind: &EditKind, row: usize, undo: bool) {
    let apply_insert_char = |lines: &mut Vec<String>, c: char, row: usize, col: usize| {
        let line = &mut lines[row];
        let idx = char_to_byte(line, col);
        line.insert(idx, c);
    };
    let apply_delete_char = |lines: &mut Vec<String>, row: usize, col: usize| {
        let line = &mut lines[row];
        let idx = char_to_byte(line, col);
        if idx < line.len() {
            line.remove(idx);
        }
    };
    let apply_insert_newline = |lines: &mut Vec<String>, row: usize, col: usize| {
        let line = &mut lines[row];
        let idx = char_to_byte(line, col);
        let next = line[idx..].to_string();
        line.truncate(idx);
        lines.insert(row + 1, next);
    };
    let apply_delete_newline = |lines: &mut Vec<String>, row: usize| {
        if row + 1 < lines.len() {
            let next = lines.remove(row + 1);
            lines[row].push_str(&next);
        }
    };
    let apply_insert_str = |lines: &mut Vec<String>, s: &str, row: usize, col: usize| {
        let line = &mut lines[row];
        let idx = char_to_byte(line, col);
        line.insert_str(idx, s);
    };
    let apply_delete_str = |lines: &mut Vec<String>, s: &str, row: usize, col: usize| {
        let line = &mut lines[row];
        let start = char_to_byte(line, col);
        let end = (start + s.len()).min(line.len());
        line.replace_range(start..end, "");
    };
    let apply_insert_chunk = |lines: &mut Vec<String>, chunk: &[String], row: usize, col: usize| {
        if chunk.is_empty() {
            return;
        }
        let line = &mut lines[row];
        let idx = char_to_byte(line, col);
        let tail = line[idx..].to_string();
        line.truncate(idx);
        line.push_str(&chunk[0]);
        let mut insert_row = row + 1;
        for (i, piece) in chunk.iter().enumerate().skip(1) {
            if i == chunk.len() - 1 {
                let mut last = piece.clone();
                last.push_str(&tail);
                lines.insert(insert_row, last);
            } else {
                lines.insert(insert_row, piece.clone());
            }
            insert_row += 1;
        }
        if chunk.len() == 1 {
            lines[row].push_str(&tail);
        }
    };
    let apply_delete_chunk = |lines: &mut Vec<String>, chunk: &[String], row: usize, col: usize| {
        if chunk.is_empty() {
            return;
        }
        let end_row = row + chunk.len() - 1;
        let end_col = col_count(&chunk[chunk.len() - 1]) + if chunk.len() == 1 { col } else { 0 };
        let end_row = end_row.min(lines.len() - 1);
        let tail = {
            let last = &lines[end_row];
            let idx = char_to_byte(last, end_col);
            last[idx.min(last.len())..].to_string()
        };
        let line = &mut lines[row];
        let idx = char_to_byte(line, col);
        line.truncate(idx);
        line.push_str(&tail);
        for _ in row..end_row {
            if row + 1 < lines.len() {
                lines.remove(row + 1);
            }
        }
    };

    match (kind, undo) {
        (EditKind::InsertChar(c, col), false) => apply_insert_char(lines, *c, row, *col),
        (EditKind::InsertChar(_, col), true) => apply_delete_char(lines, row, *col),
        (EditKind::DeleteChar(_, col), false) => apply_delete_char(lines, row, *col),
        (EditKind::DeleteChar(c, col), true) => apply_insert_char(lines, *c, row, *col),
        (EditKind::InsertNewline(col), false) => apply_insert_newline(lines, row, *col),
        (EditKind::InsertNewline(_), true) => apply_delete_newline(lines, row),
        (EditKind::DeleteNewline(_), false) => apply_delete_newline(lines, row),
        (EditKind::DeleteNewline(col), true) => apply_insert_newline(lines, row, *col),
        (EditKind::InsertStr(s, col), false) => apply_insert_str(lines, s, row, *col),
        (EditKind::InsertStr(s, col), true) => apply_delete_str(lines, s, row, *col),
        (EditKind::DeleteStr(s, col), false) => apply_delete_str(lines, s, row, *col),
        (EditKind::DeleteStr(s, col), true) => apply_insert_str(lines, s, row, *col),
        (EditKind::InsertChunk(chunk, r, col), false) => apply_insert_chunk(lines, chunk, *r, *col),
        (EditKind::InsertChunk(chunk, r, col), true) => apply_delete_chunk(lines, chunk, *r, *col),
        (EditKind::DeleteChunk(chunk, r, col), false) => apply_delete_chunk(lines, chunk, *r, *col),
        (EditKind::DeleteChunk(chunk, r, col), true) => apply_insert_chunk(lines, chunk, *r, *col),
    }
}

