        }
    }

    pub fn from_text(text: &str) -> Self {
        let lines: Vec<String> = text.split('\n').map(|l| l.to_string()).collect();
        Self::new(lines)
    }

    pub fn lines(&self) -> &[String] {
        &self.lines
    }

    pub fn text(&self) -> String {
        self.lines.join("\n")
    }

    pub fn cursor(&self) -> (usize, usize) {
        self.cursor
    }

    pub fn set_cursor_style(&mut self, style: Style) {
        self.cursor_style = style;
    }

    pub fn set_block(&mut self, block: Block<'a>) {
        self.block = Some(block);
    }

    pub fn set_max_histories(&mut self, max: usize) {
        self.history = History::new(max);
    }

    pub fn is_empty(&self) -> bool {
        self.lines.len() == 1 && self.lines[0].is_empty()
    }

    pub fn selection_range(&self) -> Option<((usize, usize), (usize, usize))> {
        let start = self.selection_start?;
        let end = self.cursor;
        if start <= end {
            Some((start, end))
        } else {
            Some((end, start))
        }
    }

    pub fn is_selecting(&self) -> bool {
        self.selection_start.is_some()
    }

    pub fn start_selection(&mut self) {
        self.selection_start = Some(self.cursor);
    }

    pub fn cancel_selection(&mut self) {
        self.selection_start = None;
    }

    pub fn select_all(&mut self) {
        self.move_cursor(CursorMove::Jump(0, 0));
        self.selection_start = Some((0, 0));
        self.move_cursor(CursorMove::Bottom);
        self.move_cursor(CursorMove::End);
    }

    fn push_history(&mut self, kind: EditKind, cursor_before: (usize, usize)) {
        let edit = Edit {
            kind,
            cursor_before,
            cursor_after: self.cursor,
        };
        self.history.push(edit);
    }

    pub fn insert_char(&mut self, c: char) {
        if c == '\n' || c == '\r' {
            self.insert_newline();
            return;
        }
        self.delete_selection(false);
        let (row, col) = self.cursor;
        let before = self.cursor;
        apply_edit(&mut self.lines, &EditKind::InsertChar(c, col), row, false);
        self.cursor = (row, col + 1);
        self.push_history(EditKind::InsertChar(c, col), before);
    }

    pub fn insert_str<S: AsRef<str>>(&mut self, s: S) -> bool {
        let s = s.as_ref();
        if s.is_empty() {
            return false;
        }
        self.delete_selection(false);
        let pieces: Vec<&str> = s.split('\n').collect();
        if pieces.len() == 1 {
            let (row, col) = self.cursor;
            let before = self.cursor;
            apply_edit(&mut self.lines, &EditKind::InsertStr(s.to_string(), col), row, false);
            self.cursor = (row, col + col_count(s));
            self.push_history(EditKind::InsertStr(s.to_string(), col), before);
            return true;
        }
        let chunk: Vec<String> = pieces.iter().map(|p| p.to_string()).collect();
        self.insert_chunk(chunk)
    }

    fn insert_chunk(&mut self, chunk: Vec<String>) -> bool {
        if chunk.is_empty() {
            return false;
        }
        let (row, col) = self.cursor;
        let before = self.cursor;
        let last_len = col_count(&chunk[chunk.len() - 1]);
        let kind = EditKind::InsertChunk(chunk, row, col);
        apply_edit(&mut self.lines, &kind, row, false);
        self.cursor = (row + match &kind {
            EditKind::InsertChunk(c, _, _) => c.len() - 1,
            _ => 0,
        }, last_len);
        self.push_history(kind, before);
        true
    }

    pub fn insert_newline(&mut self) {
        self.delete_selection(false);
        let (row, col) = self.cursor;
        let before = self.cursor;
        apply_edit(&mut self.lines, &EditKind::InsertNewline(col), row, false);
        self.cursor = (row + 1, 0);
        self.push_history(EditKind::InsertNewline(col), before);
    }

    pub fn insert_tab(&mut self) -> bool {
        if self.tab_len == 0 {
            return false;
        }
        if self.hard_tab_indent {
            self.insert_char('\t');
            return true;
        }
        let (_, col) = self.cursor;
        let width: usize = self.lines[self.cursor.0]
            .chars()
            .take(col)
            .map(|c| c.width().unwrap_or(0))
            .sum();
        let len = self.tab_len as usize - (width % self.tab_len as usize);
        let spaces = " ".repeat(len);
        self.insert_str(spaces)
    }

    pub fn delete_newline(&mut self) -> bool {
        let (row, _) = self.cursor;
        if row == 0 {
            return false;
        }
        let before = self.cursor;
        let prev_len = col_count(&self.lines[row - 1]);
        apply_edit(&mut self.lines, &EditKind::DeleteNewline(prev_len), row - 1, false);
        self.cursor = (row - 1, prev_len);
        self.push_history(EditKind::DeleteNewline(prev_len), before);
        true
    }

    /// Delete one character before the cursor (Backspace).
    pub fn delete_char(&mut self) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        let (row, col) = self.cursor;
        if col == 0 {
            return self.delete_newline();
        }
        let before = self.cursor;
        let c = self.lines[row].chars().nth(col - 1).unwrap();
        apply_edit(&mut self.lines, &EditKind::DeleteChar(c, col - 1), row, false);
        self.cursor = (row, col - 1);
        self.push_history(EditKind::DeleteChar(c, col - 1), before);
        true
    }

    /// Delete one character next to the cursor (Delete).
    pub fn delete_next_char(&mut self) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        let before = self.cursor;
        if self.move_cursor_internal(CursorMove::Forward, false) {
            let moved = self.cursor != before;
            if moved {
                let changed = self.delete_char();
                return changed;
            }
        }
        false
    }

    pub fn delete_line_by_end(&mut self) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        let (row, col) = self.cursor;
        let line_len = col_count(&self.lines[row]);
        if col >= line_len {
            // delete the newline next to cursor
            if row + 1 < self.lines.len() {
                let before = self.cursor;
                apply_edit(&mut self.lines, &EditKind::DeleteNewline(col), row, false);
                self.cursor = (row, col);
                self.push_history(EditKind::DeleteNewline(col), before);
                return true;
            }
            return false;
        }
        let deleted: String = self.lines[row].chars().skip(col).collect();
        self.yank = vec![deleted.clone()];
        let before = self.cursor;
        apply_edit(&mut self.lines, &EditKind::DeleteStr(deleted.clone(), col), row, false);
        self.push_history(EditKind::DeleteStr(deleted, col), before);
        true
    }

    pub fn delete_line_by_head(&mut self) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        let (row, col) = self.cursor;
        if col == 0 {
            return self.delete_newline();
        }
        let deleted: String = self.lines[row].chars().take(col).collect();
        self.yank = vec![deleted.clone()];
        let before = self.cursor;
        apply_edit(&mut self.lines, &EditKind::DeleteStr(deleted.clone(), 0), row, false);
        self.cursor = (row, 0);
        self.push_history(EditKind::DeleteStr(deleted, 0), before);
        true
    }

    pub fn delete_word(&mut self) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        let (row, col) = self.cursor;
        if col == 0 {
            return self.delete_newline();
        }
        let start = find_word_start_backward(&self.lines[row], col);
        if start == col {
            return false;
        }
        let deleted: String = self.lines[row]
            .chars()
            .skip(start)
            .take(col - start)
            .collect();
        self.yank = vec![deleted.clone()];
        let before = self.cursor;
        apply_edit(&mut self.lines, &EditKind::DeleteStr(deleted.clone(), start), row, false);
        self.cursor = (row, start);
        self.push_history(EditKind::DeleteStr(deleted, start), before);
        true
    }

    pub fn delete_next_word(&mut self) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        let (row, col) = self.cursor;
        let line = &self.lines[row];
        let line_len = col_count(line);
        if col >= line_len {
            // join next line
            if row + 1 < self.lines.len() {
                let before = self.cursor;
                apply_edit(&mut self.lines, &EditKind::DeleteNewline(col), row, false);
                self.push_history(EditKind::DeleteNewline(col), before);
                return true;
            }
            return false;
        }
        let end = find_word_exclusive_end_forward(line, col).unwrap_or(line_len);
        if end == col {
            return false;
        }
        let deleted: String = line.chars().skip(col).take(end - col).collect();
        self.yank = vec![deleted.clone()];
        let before = self.cursor;
        apply_edit(&mut self.lines, &EditKind::DeleteStr(deleted.clone(), col), row, false);
        self.push_history(EditKind::DeleteStr(deleted, col), before);
        true
    }

    fn delete_range(&mut self, start: (usize, usize), end: (usize, usize), should_yank: bool) {
        self.cursor = start;
        if start.0 == end.0 {
            let deleted: String = self.lines[start.0]
                .chars()
                .skip(start.1)
                .take(end.1 - start.1)
                .collect();
            if deleted.is_empty() {
                return;
            }
            if should_yank {
                self.yank = vec![deleted.clone()];
            }
            let before = end;
            apply_edit(&mut self.lines, &EditKind::DeleteStr(deleted.clone(), start.1), start.0, false);
            self.push_history(EditKind::DeleteStr(deleted, start.1), before);
            return;
        }
        let mut chunk: Vec<String> = Vec::new();
        chunk.push(self.lines[start.0].chars().skip(start.1).collect());
        for r in (start.0 + 1)..end.0 {
            chunk.push(self.lines[r].clone());
        }
        chunk.push(self.lines[end.0].chars().take(end.1).collect());
        if should_yank {
            self.yank = chunk.clone();
        }
        let before = end;
        let kind = EditKind::DeleteChunk(chunk, start.0, start.1);
        apply_edit(&mut self.lines, &kind, start.0, false);
        self.push_history(kind, before);
    }

    fn delete_selection(&mut self, should_yank: bool) -> bool {
        if let Some((start, end)) = self.selection_range() {
            self.cancel_selection();
            if start == end {
                return false;
            }
            self.delete_range(start, end, should_yank);
            return true;
        }
        false
    }

    pub fn cut(&mut self) -> bool {
        self.delete_selection(true)
    }

    pub fn copy(&mut self) {
        if let Some((start, end)) = self.selection_range() {
            if start.0 == end.0 {
                let text: String = self.lines[start.0]
                    .chars()
                    .skip(start.1)
                    .take(end.1 - start.1)
                    .collect();
                self.yank = vec![text];
            } else {
                let mut chunk: Vec<String> = Vec::new();
                chunk.push(self.lines[start.0].chars().skip(start.1).collect());
                for r in (start.0 + 1)..end.0 {
                    chunk.push(self.lines[r].clone());
                }
                chunk.push(self.lines[end.0].chars().take(end.1).collect());
                self.yank = chunk;
            }
        }
        self.cancel_selection();
    }

    pub fn paste(&mut self) -> bool {
        self.delete_selection(false);
        if self.yank.is_empty() {
            return false;
        }
        if self.yank.len() == 1 {
            let s = self.yank[0].clone();
            return self.insert_str(s);
        }
        let chunk = self.yank.clone();
        self.insert_chunk(chunk)
    }

    pub fn yank_text(&self) -> String {
        self.yank.join("\n")
    }

    pub fn set_yank_text(&mut self, text: &str) {
        self.yank = text.split('\n').map(|s| s.to_string()).collect();
    }

    pub fn selected_text(&self) -> Option<String> {
        let (start, end) = self.selection_range()?;
        if start.0 == end.0 {
            return Some(
                self.lines[start.0]
                    .chars()
                    .skip(start.1)
                    .take(end.1 - start.1)
                    .collect(),
            );
        }
        let mut parts: Vec<String> = Vec::new();
        parts.push(self.lines[start.0].chars().skip(start.1).collect());
        for r in (start.0 + 1)..end.0 {
            parts.push(self.lines[r].clone());
        }
        parts.push(self.lines[end.0].chars().take(end.1).collect());
        Some(parts.join("\n"))
    }

    pub fn undo(&mut self) -> bool {
        if self.history.index == 0 {
            return false;
        }
        self.history.index -= 1;
        let edit = self.history.edits[self.history.index].clone();
        let row = match &edit.kind {
            EditKind::InsertChunk(_, r, _) | EditKind::DeleteChunk(_, r, _) => *r,
            _ => edit.cursor_before.0.min(edit.cursor_after.0),
        };
        let row = match &edit.kind {
            EditKind::InsertNewline(_) => edit.cursor_before.0,
            EditKind::DeleteNewline(_) => edit.cursor_after.0,
            EditKind::InsertChar(..) | EditKind::DeleteChar(..) | EditKind::InsertStr(..) | EditKind::DeleteStr(..) => edit.cursor_after.0.min(edit.cursor_before.0).max(match &edit.kind {
                EditKind::InsertChar(..) | EditKind::InsertStr(..) => edit.cursor_before.0,
                _ => edit.cursor_after.0,
            }),
            _ => row,
        };
        apply_edit(&mut self.lines, &edit.kind, row, true);
        self.cursor = edit.cursor_before;
        self.cancel_selection();
        true
    }

    pub fn redo(&mut self) -> bool {
        if self.history.index >= self.history.edits.len() {
            return false;
        }
        let edit = self.history.edits[self.history.index].clone();
        self.history.index += 1;
        let row = match &edit.kind {
            EditKind::InsertChunk(_, r, _) | EditKind::DeleteChunk(_, r, _) => *r,
            EditKind::InsertNewline(_) => edit.cursor_before.0,
            EditKind::DeleteNewline(_) => edit.cursor_after.0,
            EditKind::InsertChar(..) | EditKind::InsertStr(..) => edit.cursor_before.0,
            EditKind::DeleteChar(..) | EditKind::DeleteStr(..) => edit.cursor_after.0,
        };
        apply_edit(&mut self.lines, &edit.kind, row, false);
        self.cursor = edit.cursor_after;
        self.cancel_selection();
        true
    }

    pub fn clear_history(&mut self) {
        self.history.clear();
    }

    pub fn move_cursor(&mut self, m: CursorMove) {
        let shift = self.selection_start.is_some();
        self.move_cursor_internal(m, shift);
    }

    pub fn move_cursor_with_shift(&mut self, m: CursorMove, shift: bool) {
        if shift && self.selection_start.is_none() {
            self.selection_start = Some(self.cursor);
        } else if !shift {
            self.selection_start = None;
        }
        self.move_cursor_internal(m, true);
    }

    fn move_cursor_internal(&mut self, m: CursorMove, _shift: bool) -> bool {
        if let Some(pos) = self.next_pos(m) {
            self.cursor = pos;
            return true;
        }
        false
    }

    fn fit_col(col: usize, line: &str) -> usize {
        col.min(col_count(line))
    }

    fn next_pos(&self, m: CursorMove) -> Option<(usize, usize)> {
        let (row, col) = self.cursor;
        let lines = &self.lines;
        match m {
            CursorMove::Forward => {
                if col >= col_count(&lines[row]) {
                    if row + 1 < lines.len() {
                        Some((row + 1, 0))
                    } else {
                        None
                    }
                } else {
                    Some((row, col + 1))
                }
            }
            CursorMove::Back => {
                if col == 0 {
                    if row > 0 {
                        Some((row - 1, col_count(&lines[row - 1])))
                    } else {
                        None
                    }
                } else {
                    Some((row, col - 1))
                }
            }
            CursorMove::Up => {
                if row == 0 {
                    None
                } else {
                    Some((row - 1, Self::fit_col(col, &lines[row - 1])))
                }
            }
            CursorMove::Down => {
                if row + 1 >= lines.len() {
                    None
                } else {
                    Some((row + 1, Self::fit_col(col, &lines[row + 1])))
                }
            }
            CursorMove::Head => Some((row, 0)),
            CursorMove::End => Some((row, col_count(&lines[row]))),
            CursorMove::Top => Some((0, Self::fit_col(col, &lines[0]))),
            CursorMove::Bottom => {
                let last = lines.len() - 1;
                Some((last, Self::fit_col(col, &lines[last])))
            }
            CursorMove::WordForward => {
                if let Some(c) = find_word_start_forward(&lines[row], col) {
                    Some((row, c))
                } else if row + 1 < lines.len() {
                    Some((row + 1, 0))
                } else {
                    Some((row, col_count(&lines[row])))
                }
            }
            CursorMove::WordEnd => {
                if let Some(c) = find_word_inclusive_end_forward(&lines[row], col + 1) {
                    Some((row, c))
                } else {
                    let mut r = row;
                    loop {
                        if r + 1 >= lines.len() {
                            return Some((r, col_count(&lines[r])));
                        }
                        r += 1;
                        if let Some(c) = find_word_inclusive_end_forward(&lines[r], 0) {
                            return Some((r, c));
                        }
                    }
                }
            }
            CursorMove::WordBack => {
                if col > 0 {
                    Some((row, find_word_start_backward(&lines[row], col)))
                } else if row > 0 {
                    Some((row - 1, col_count(&lines[row - 1])))
                } else {
                    None
                }
            }
            CursorMove::ParagraphForward => {
                let mut prev_is_empty = lines[row].is_empty();
                for (r, line) in lines.iter().enumerate().skip(row + 1) {
                    let is_empty = line.is_empty();
                    if !is_empty && prev_is_empty {
                        return Some((r, 0));
                    }
                    prev_is_empty = is_empty;
                }
                let last = lines.len() - 1;
                Some((last, col_count(&lines[last])))
            }
            CursorMove::ParagraphBack => {
                let mut prev_is_empty = lines[row].is_empty();
                let mut r = row;
                while r > 0 {
                    r -= 1;
                    let is_empty = lines[r].is_empty();
                    if is_empty && !prev_is_empty {
                        return Some((r + 1, 0));
                    }
                    prev_is_empty = is_empty;
                }
                Some((0, 0))
            }
            CursorMove::Jump(r, c) => {
                let r = (r as usize).min(lines.len() - 1);
                let c = Self::fit_col(c as usize, &lines[r]);
                Some((r, c))
            }
            CursorMove::InViewport => {
                let (top_row, top_col) = self.scroll_top;
                let (width, height) = self.viewport;
                let row_bottom = (top_row as usize + height as usize).saturating_sub(1);
                let col_bottom = (top_col as usize + width as usize).saturating_sub(1);
                let r = row.clamp(top_row as usize, row_bottom.max(top_row as usize));
                let r = r.min(lines.len() - 1);
                let c = col.clamp(top_col as usize, col_bottom.max(top_col as usize));
                let c = Self::fit_col(c, &lines[r]);
                Some((r, c))
            }
        }
    }

    pub fn scroll_rows(&mut self, rows: i32) {
        let (top_row, top_col) = self.scroll_top;
        let new_top = (top_row as i32 + rows).max(0) as u16;
        self.scroll_top = (new_top, top_col);
        let shift = self.selection_start.is_some();
        self.move_cursor_internal(CursorMove::InViewport, shift);
    }

    pub fn scroll_page_down(&mut self) {
        let rows = self.viewport.1 as i32;
        self.scroll_rows(rows);
    }

    pub fn scroll_page_up(&mut self) {
        let rows = self.viewport.1 as i32;
        self.scroll_rows(-rows);
    }

    pub fn scroll_half_page_down(&mut self) {
        let rows = (self.viewport.1 / 2) as i32;
        self.scroll_rows(rows);
    }

    pub fn scroll_half_page_up(&mut self) {
        let rows = (self.viewport.1 / 2) as i32;
        self.scroll_rows(-rows);
    }

    pub fn widget(&self) -> TextAreaWidget<'_, 'a> {
        TextAreaWidget { ta: self }
    }

    /// Update viewport after rendering (called from the widget).
    fn store_viewport(&self, top_row: u16, top_col: u16, width: u16, height: u16) {
        // interior mutability through raw pointer is avoided; use a Cell-like approach
        let me = self as *const Self as *mut Self;
        unsafe {
            (*me).scroll_top = (top_row, top_col);
            (*me).viewport = (width, height);
        }
    }
}

fn next_scroll_top(prev_top: u16, cursor: u16, length: u16) -> u16 {
    if cursor < prev_top {
        cursor
    } else if prev_top + length <= cursor {
        cursor + 1 - length
    } else {
        prev_top
    }
}

pub struct TextAreaWidget<'b, 'a> {
    ta: &'b TextArea<'a>,
}

impl<'b, 'a> Widget for TextAreaWidget<'b, 'a> {
    fn render(self, area: Rect, buf: &mut Buffer) {
        let ta = self.ta;
        let inner = if let Some(block) = &ta.block {
            block.clone().render(area, buf);
            block.inner(area)
        } else {
            area
        };
        if inner.width == 0 || inner.height == 0 {
            ta.store_viewport(ta.scroll_top.0, ta.scroll_top.1, inner.width, inner.height);
            return;
        }
        buf.set_style(inner, ta.style);

        let (cursor_row, cursor_col) = ta.cursor;
        let (prev_top_row, prev_top_col) = ta.scroll_top;
        let top_row = next_scroll_top(prev_top_row, cursor_row as u16, inner.height);
        // horizontal scroll is based on display width of the cursor column
        let cursor_width: usize = ta.lines[cursor_row]
            .chars()
            .take(cursor_col)
            .map(|c| display_width(c, ta.tab_len))
            .sum();
        let top_col = next_scroll_top(prev_top_col, cursor_width as u16, inner.width);
        ta.store_viewport(top_row, top_col, inner.width, inner.height);

        let selection = ta.selection_range();
        let show_placeholder = ta.is_empty() && !ta.placeholder.is_empty();

        for (i, row) in (top_row as usize..).take(inner.height as usize).enumerate() {
            let y = inner.y + i as u16;
            if row >= ta.lines.len() {
                break;
            }
            let line = &ta.lines[row];
            let mut spans: Vec<Span> = Vec::new();
            let is_cursor_row = row == cursor_row;
            let base = if is_cursor_row {
                ta.style.patch(ta.cursor_line_style)
            } else {
                ta.style
            };

            if show_placeholder && row == 0 {
                // placeholder with cursor at start
                if ta.show_cursor {
                    let mut chars = ta.placeholder.chars();
                    if let Some(first) = chars.next() {
                        spans.push(Span::styled(first.to_string(), ta.cursor_style));
                        spans.push(Span::styled(chars.collect::<String>(), ta.placeholder_style));
                    } else {
                        spans.push(Span::styled(" ", ta.cursor_style));
                    }
                } else {
                    spans.push(Span::styled(ta.placeholder.clone(), ta.placeholder_style));
                }
            } else {
                let mut current = String::new();
                let mut current_style = base;
                let mut width_so_far: usize = 0;
                let flush = |spans: &mut Vec<Span>, current: &mut String, style: Style| {
                    if !current.is_empty() {
                        spans.push(Span::styled(std::mem::take(current), style));
                    }
                };
                for (col, c) in line.chars().enumerate() {
                    let in_sel = selection
                        .map(|(s, e)| {
                            let pos = (row, col);
                            pos >= s && pos < e
                        })
                        .unwrap_or(false);
                    let is_cursor = ta.show_cursor && is_cursor_row && col == cursor_col;
                    let style = if is_cursor {
                        base.patch(ta.cursor_style)
                    } else if in_sel {
                        base.patch(ta.selection_style)
                    } else {
                        base
                    };
                    let text: String = if c == '\t' {
                        let n = ta.tab_len as usize;
                        let pad = if n == 0 { 0 } else { n - (width_so_far % n) };
                        " ".repeat(pad)
                    } else {
                        c.to_string()
                    };
                    width_so_far += display_width(c, ta.tab_len);
                    if style != current_style {
                        flush(&mut spans, &mut current, current_style);
                        current_style = style;
                    }
                    current.push_str(&text);
                }
                flush(&mut spans, &mut current, current_style);
                if ta.show_cursor && is_cursor_row && cursor_col >= col_count(line) {
                    spans.push(Span::styled(" ", base.patch(ta.cursor_style)));
                }
            }

            // apply horizontal scroll by skipping `top_col` cells
            let line_widget = Line::from(spans);
            render_line_scrolled(&line_widget, top_col, inner.x, y, inner.width, buf, base);
        }
    }
}

fn display_width(c: char, tab_len: u8) -> usize {
    if c == '\t' {
        tab_len as usize
    } else {
        c.width().unwrap_or(0)
    }
}

fn render_line_scrolled(
    line: &Line,
    skip_cells: u16,
    x: u16,
    y: u16,
    width: u16,
    buf: &mut Buffer,
    base: Style,
) {
    // fill row with base style
    for cx in x..x + width {
        if let Some(cell) = buf.cell_mut((cx, y)) {
            cell.set_symbol(" ");
            cell.set_style(base);
        }
    }
    let mut cell_pos: usize = 0;
    let mut out_x = x;
    let end_x = x + width;
    for span in line.spans.iter() {
        for g in unicode_segmentation::UnicodeSegmentation::graphemes(span.content.as_ref(), true) {
            let w = unicode_width::UnicodeWidthStr::width(g);
            if w == 0 {
                continue;
            }
            if cell_pos + w <= skip_cells as usize {
                cell_pos += w;
                continue;
            }
            if out_x + w as u16 > end_x {
                return;
            }
            if let Some(cell) = buf.cell_mut((out_x, y)) {
                cell.set_symbol(g);
                cell.set_style(span.style);
            }
            for k in 1..w {
                if let Some(cell) = buf.cell_mut((out_x + k as u16, y)) {
                    cell.set_symbol("");
                    cell.set_style(span.style);
                }
            }
            out_x += w as u16;
            cell_pos += w;
        }
    }
}
