        let mut prev = 0;
        for p in points {
            let piece = &word.word[prev..p];
            result.push(Word {
                word: piece,
                width: str_width(piece),
                whitespace: "",
            });
            prev = p;
        }
        let last = &word.word[prev..];
        result.push(Word {
            word: last,
            width: str_width(last),
            whitespace: word.whitespace,
        });
    }
    result
}

fn break_words<'a>(words: Vec<Word<'a>>, line_width: usize) -> Vec<Word<'a>> {
    let mut result = Vec::new();
    for word in words {
        if word.width <= line_width {
            result.push(word);
            continue;
        }
        let mut offset = 0;
        let mut width = 0;
        for (idx, ch) in word.word.char_indices() {
            let w = ch.width().unwrap_or(0);
            if width > 0 && width + w > line_width {
                result.push(Word {
                    word: &word.word[offset..idx],
