            vec![
                "a-very-long-tag-name-that-".to_string(),
                "exceeds-the-width-of-the-list-".to_string(),
                "for-sure ok".to_string()
            ]
        );
        assert_eq!(
            wrap_line("path/to/some/very/long/directory/name/that/exceeds/width yes", 31),
            vec![
                "path/to/some/very/long/".to_string(),
                "directory/name/that/exceeds/".to_string(),
                "width yes".to_string()
            ]
        );
        assert_eq!(
            wrap_line("snake_case_identifier_that_is_very_long_indeed_more_than_31 chars", 31),
            vec![
                "snake_case_identifier_that_is_v".to_string(),
                "ery_long_indeed_more_than_31".to_string(),
                "chars".to_string()
            ]
        );
        assert_eq!(
            wrap_line("tést ünicöde 中文字符 emoji 😀 end", 31),
            vec!["tést ünicöde 中文字符 emoji".to_string(), "😀 end".to_string()]
        );
        assert_eq!(
            wrap_line(&format!("{} z", "中".repeat(15)), 31),
