        if prev.filter(|ch| ch.is_alphanumeric()).is_some()
            && next.filter(|ch| ch.is_alphanumeric()).is_some()
        {
            splits.push(idx + 1);
        }
    }
    splits
}

fn split_words<'a>(words: Vec<Word<'a>>) -> Vec<Word<'a>> {
    let mut result = Vec::new();
    for word in words {
        let points = hyphen_split_points(word.word);
        if points.is_empty() {
            result.push(word);
            continue;
        }
        let mut prev = 0;
        for p in points {
            let piece = &word.word[prev..p];
            result.push(Word {
                word: piece,
                width: str_width(piece),
                whitespace: "",
            });
            prev = p;
        }
        let last = &word.word[prev..];
        result.push(Word {
            word: last,
            width: str_width(last),
            whitespace: word.whitespace,
        });
    }
    result
}

fn break_words<'a>(words: Vec<Word<'a>>, line_width: usize) -> Vec<Word<'a>> {
    let mut result = Vec::new();
    for word in words {
        if word.width <= line_width {
            result.push(word);
            continue;
        }
        let mut offset = 0;
        let mut width = 0;
        for (idx, ch) in word.word.char_indices() {
            let w = ch.width().unwrap_or(0);
            if width > 0 && width + w > line_width {
                result.push(Word {
                    word: &word.word[offset..idx],
                    width,
                    whitespace: "",
                });
                offset = idx;
                width = w;
            } else {
                width += w;
            }
        }
        if offset < word.word.len() {
            result.push(Word {
                word: &word.word[offset..],
                width,
                whitespace: word.whitespace,
            });
        }
    }
    result
}

const NLINE_PENALTY: f64 = 1000.0;
const OVERFLOW_PENALTY: f64 = 2500.0;
const SHORT_LAST_LINE_FRACTION: f64 = 4.0;
const SHORT_LAST_LINE_PENALTY: f64 = 25.0;

fn wrap_optimal_fit<'a, 'b>(fragments: &'b [Word<'a>], line_width: usize) -> Vec<&'b [Word<'a>]> {
    let n = fragments.len();
    if n == 0 {
        return vec![];
    }
    // prefix sums of word width + whitespace width
    let mut prefix = vec![0.0f64; n + 1];
    for (i, w) in fragments.iter().enumerate() {
        prefix[i + 1] = prefix[i] + (w.width + w.whitespace_width()) as f64;
    }
    let target = line_width as f64;
    let line_width_of = |i: usize, j: usize| -> f64 {
        // fragments i..j, excluding whitespace of the last one
        prefix[j] - prefix[i] - fragments[j - 1].whitespace_width() as f64
    };
    let cost = |i: usize, j: usize| -> f64 {
        let lw = line_width_of(i, j);
        let mut cost = 0.0;
        if lw > target {
            cost += (lw - target) * OVERFLOW_PENALTY;
        } else if j < n {
            let gap = target - lw;
            cost += gap * gap;
        } else if i + 1 == j && lw < target / SHORT_LAST_LINE_FRACTION {
            cost += SHORT_LAST_LINE_PENALTY;
        }
        cost += NLINE_PENALTY;
        cost
    };
    let mut minima = vec![f64::INFINITY; n + 1];
    let mut back = vec![0usize; n + 1];
    minima[0] = 0.0;
    for j in 1..=n {
        for i in 0..j {
            let c = minima[i] + cost(i, j);
            if c < minima[j] {
                minima[j] = c;
                back[j] = i;
            }
        }
    }
    let mut lines = Vec::new();
    let mut j = n;
    while j > 0 {
        let i = back[j];
        lines.push(&fragments[i..j]);
        j = i;
    }
    lines.reverse();
    lines
}

/// Wraps a single line of text into lines not exceeding `width` display cells
/// (when possible), following an optimal-fit algorithm.
pub fn wrap_line(line: &str, width: usize) -> Vec<String> {
    let width = width.max(1);
    let words = find_words(line);
    let words = split_words(words);
    let words = break_words(words, width);
    let wrapped = wrap_optimal_fit(&words, width);
    let mut result = Vec::new();
    for frags in wrapped {
        let mut s = String::new();
        for (k, w) in frags.iter().enumerate() {
            s.push_str(w.word);
            if k + 1 < frags.len() {
                s.push_str(w.whitespace);
            }
        }
        result.push(s);
    }
    if result.is_empty() {
        result.push(String::new());
    }
    result
}

/// Wraps text that may contain newlines.
pub fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut result = Vec::new();
    for line in text.split('\n') {
        result.extend(wrap_line(line, width));
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        assert_eq!(
            wrap_line("Second entry with a quite long title that should be truncated at some point", 31),
            vec![
                "Second entry with a quite long".to_string(),
                "title that should be truncated".to_string(),
                "at some point".to_string()
            ]
        );
        assert_eq!(wrap_line(&"a".repeat(75), 31).len(), 3);
        assert_eq!(
            wrap_line("a-very-long-tag-name-that-exceeds-the-width-of-the-list-for-sure ok", 31),
            vec![
                "a-very-long-tag-name-that-".to_string(),
                "exceeds-the-width-of-the-list-".to_string(),
