use std::collections::BTreeSet;

use anyhow::Result;
use chrono::{DateTime, Datelike, Utc};

use crate::backend::{DataProvider, Entry, EntryDraft};
use crate::settings::Settings;

use filter::Filter;
use history::{History, HistoryItem};
use sorter::Sorter;

pub struct App {
    pub provider: Box<dyn DataProvider>,
    pub settings: Settings,
    pub entries: Vec<Entry>,
    pub sorter: Sorter,
    pub filter: Option<Filter>,
    pub history: History,
    pub current_entry_id: Option<u32>,
}

impl App {
    pub fn new(provider: Box<dyn DataProvider>, settings: Settings) -> Self {
        let history_limit = settings.history_limit;
        Self {
            provider,
            settings,
            entries: Vec::new(),
            sorter: Sorter::default(),
            filter: None,
            history: History::new(history_limit),
            current_entry_id: None,
        }
    }

    pub fn load_entries(&mut self) -> Result<()> {
        log::trace!("Loading entries");
        self.entries = self.provider.load_all_entries()?;
        self.sort_entries();
        Ok(())
    }

    pub fn sort_entries(&mut self) {
        let sorter = self.sorter.clone();
        self.entries.sort_by(|a, b| sorter.compare(a, b));
    }

    pub fn get_entry(&self, id: u32) -> Option<&Entry> {
        self.entries.iter().find(|e| e.id == id)
    }

    pub fn get_entry_mut(&mut self, id: u32) -> Option<&mut Entry> {
        self.entries.iter_mut().find(|e| e.id == id)
    }

    /// Returns the entries which pass the current filter, in the sorted order.
    pub fn visible_entries(&self) -> Vec<&Entry> {
        match &self.filter {
            Some(filter) => self
                .entries
                .iter()
                .filter(|e| filter.check_entry(e))
                .collect(),
            None => self.entries.iter().collect(),
        }
    }

    pub fn all_tags(&self) -> Vec<String> {
        let set: BTreeSet<String> = self
            .entries
            .iter()
            .flat_map(|e| e.tags.iter().cloned())
            .collect();
        set.into_iter().collect()
    }

    pub fn add_entry(&mut self, draft: EntryDraft) -> Result<Entry> {
        log::trace!("Adding entry");
        let entry = self.provider.add_entry(draft)?;
        log::trace!("History Register Add: Entry: {:?}", entry);
        self.history.register(HistoryItem::Add(entry.clone()));
        self.entries.push(entry.clone());
        self.sort_entries();
        Ok(entry)
    }

    fn add_entry_no_history(&mut self, draft: EntryDraft) -> Result<Entry> {
        let entry = self.provider.add_entry(draft)?;
        self.entries.push(entry.clone());
        self.sort_entries();
        Ok(entry)
    }

    pub fn update_entry(&mut self, entry: Entry) -> Result<()> {
        log::trace!("Updating entry {}", entry.id);
        if let Some(old) = self.get_entry(entry.id).cloned() {
            let updated = self.provider.update_entry(entry)?;
            self.history
                .register(HistoryItem::Change(old, updated.clone()));
            if let Some(e) = self.get_entry_mut(updated.id) {
                *e = updated;
            }
            self.sort_entries();
        }
        Ok(())
    }

    fn update_entry_no_history(&mut self, entry: Entry) -> Result<()> {
        let updated = self.provider.update_entry(entry)?;
        if let Some(e) = self.get_entry_mut(updated.id) {
            *e = updated;
        }
        self.sort_entries();
        Ok(())
    }

    pub fn remove_entry(&mut self, id: u32) -> Result<()> {
        log::trace!("Removing entry {}", id);
        if let Some(entry) = self.get_entry(id).cloned() {
            self.provider.remove_entry(id)?;
            self.history.register(HistoryItem::Remove(entry));
            self.entries.retain(|e| e.id != id);
        }
        Ok(())
    }

    pub fn remove_entries(&mut self, ids: &[u32]) -> Result<()> {
        log::trace!("Removing entries {:?}", ids);
        let removed: Vec<Entry> = self
            .entries
            .iter()
            .filter(|e| ids.contains(&e.id))
            .cloned()
            .collect();
        if removed.is_empty() {
            return Ok(());
        }
        self.provider.remove_entries(ids)?;
        self.history.register(HistoryItem::RemoveMultiple(removed));
        self.entries.retain(|e| !ids.contains(&e.id));
        Ok(())
    }

    fn remove_entries_no_history(&mut self, ids: &[u32]) -> Result<()> {
        self.provider.remove_entries(ids)?;
        self.entries.retain(|e| !ids.contains(&e.id));
        Ok(())
    }

    /// Undo the latest change. Returns the id of the entry to select if any.
    pub fn undo(&mut self) -> Result<Option<u32>> {
        let Some(item) = self.history.pop_undo() else {
            return Ok(None);
        };
        log::trace!("History undo: {:?}", item);
        let (redo_item, select) = match item {
            HistoryItem::Add(entry) => {
                self.remove_entries_no_history(&[entry.id])?;
                (HistoryItem::Add(entry), None)
            }
            HistoryItem::Remove(entry) => {
                let added = self.add_entry_no_history(EntryDraft::from_entry(&entry))?;
                let id = added.id;
                (HistoryItem::Remove(added), Some(id))
            }
            HistoryItem::RemoveMultiple(entries) => {
                let mut added_all = Vec::new();
                for entry in entries.iter() {
                    added_all.push(self.add_entry_no_history(EntryDraft::from_entry(entry))?);
                }
                let select = added_all.first().map(|e| e.id);
                (HistoryItem::RemoveMultiple(added_all), select)
            }
            HistoryItem::Change(old, new) => {
                self.update_entry_no_history(old.clone())?;
                let id = old.id;
                (HistoryItem::Change(old, new), Some(id))
            }
        };
        self.history.push_redo(redo_item);
        Ok(select)
    }

    pub fn redo(&mut self) -> Result<Option<u32>> {
        let Some(item) = self.history.pop_redo() else {
            return Ok(None);
        };
        log::trace!("History redo: {:?}", item);
        let (undo_item, select) = match item {
            HistoryItem::Add(entry) => {
                let added = self.add_entry_no_history(EntryDraft::from_entry(&entry))?;
                let id = added.id;
                (HistoryItem::Add(added), Some(id))
            }
            HistoryItem::Remove(entry) => {
                self.remove_entries_no_history(&[entry.id])?;
                (HistoryItem::Remove(entry), None)
            }
            HistoryItem::RemoveMultiple(entries) => {
                let ids: Vec<u32> = entries.iter().map(|e| e.id).collect();
                self.remove_entries_no_history(&ids)?;
                (HistoryItem::RemoveMultiple(entries), None)
            }
            HistoryItem::Change(old, new) => {
                self.update_entry_no_history(new.clone())?;
                let id = new.id;
                (HistoryItem::Change(old, new), Some(id))
            }
        };
        self.history.push_undo(undo_item);
        Ok(select)
    }
}

