//! A small fuzzy matcher (subsequence matching with smart case and a simple
//! scoring heuristic rewarding consecutive and word-start matches).

pub struct FuzzyMatch {
    pub score: i64,
    pub indices: Vec<usize>,
}

fn is_boundary(prev: Option<char>, cur: char) -> bool {
    match prev {
        None => true,
        Some(p) => {
            !p.is_alphanumeric() && cur.is_alphanumeric()
                || (p.is_lowercase() && cur.is_uppercase())
        }
    }
}

pub fn fuzzy_match(text: &str, pattern: &str) -> Option<FuzzyMatch> {
    if pattern.is_empty() {
        return Some(FuzzyMatch {
            score: 0,
            indices: Vec::new(),
        });
    }
    let smart_case_sensitive = pattern.chars().any(|c| c.is_uppercase());
    let text_chars: Vec<char> = text.chars().collect();
    let pat_chars: Vec<char> = pattern.chars().collect();

    let eq = |a: char, b: char| -> bool {
        if smart_case_sensitive {
            a == b
        } else {
            a.to_lowercase().eq(b.to_lowercase())
        }
    };

    // Greedy forward subsequence match.
    let mut indices = Vec::with_capacity(pat_chars.len());
    let mut ti = 0;
    for pc in pat_chars.iter() {
        let mut found = false;
        while ti < text_chars.len() {
            if eq(text_chars[ti], *pc) {
                indices.push(ti);
                ti += 1;
                found = true;
                break;
            }
            ti += 1;
        }
        if !found {
            return None;
        }
    }

    // Try to improve: for each matched char, if the next pattern char can be
    // matched consecutively from an earlier position we keep greedy (simple).
    let mut score: i64 = 0;
    let mut prev_idx: Option<usize> = None;
    for &idx in indices.iter() {
        let prev_char = if idx > 0 { Some(text_chars[idx - 1]) } else { None };
        let mut s = 16;
        if is_boundary(prev_char, text_chars[idx]) {
            s += 8;
        }
        if let Some(p) = prev_idx {
            if p + 1 == idx {
                s += 8;
            } else {
                s -= ((idx - p - 1) as i64).min(4);
            }
        } else {
            s -= (idx as i64).min(3);
        }
        if text_chars[idx] == pat_chars[indices.iter().position(|&i| i == idx).unwrap()] {
            s += 1;
        }
        score += s;
        prev_idx = Some(idx);
    }
    Some(FuzzyMatch { score, indices })
}
