use std::cmp::Ordering;

use serde::{Deserialize, Serialize};

use crate::backend::Entry;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum SortCriteria {
    Date,
    Priority,
    Title,
}

impl SortCriteria {
    pub const ALL: [SortCriteria; 3] = [SortCriteria::Title, SortCriteria::Date, SortCriteria::Priority];

    pub fn name(&self) -> &'static str {
        match self {
            SortCriteria::Date => "Date",
            SortCriteria::Priority => "Priority",
            SortCriteria::Title => "Title",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum SortOrder {
    Ascending,
    #[default]
    Descending,
}

impl SortOrder {
    pub fn name(&self) -> &'static str {
        match self {
            SortOrder::Ascending => "Ascending",
            SortOrder::Descending => "Descending",
        }
    }

    pub fn toggle(&mut self) {
        *self = match self {
            SortOrder::Ascending => SortOrder::Descending,
            SortOrder::Descending => SortOrder::Ascending,
        };
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Sorter {
    pub criteria: Vec<SortCriteria>,
    pub order: SortOrder,
}

impl Default for Sorter {
    fn default() -> Self {
        Self {
            criteria: vec![SortCriteria::Date, SortCriteria::Priority],
            order: SortOrder::Descending,
        }
    }
}

impl Sorter {
    pub fn compare(&self, a: &Entry, b: &Entry) -> Ordering {
        let mut ord = Ordering::Equal;
        for c in &self.criteria {
            ord = match c {
                SortCriteria::Date => a.date.cmp(&b.date),
                SortCriteria::Priority => a.priority.cmp(&b.priority),
                SortCriteria::Title => a.title.cmp(&b.title),
            };
            if ord != Ordering::Equal {
                break;
            }
        }
        match self.order {
            SortOrder::Ascending => ord,
            SortOrder::Descending => ord.reverse(),
        }
    }
}
