use std::collections::VecDeque;

use crate::backend::Entry;

#[derive(Debug, Clone)]
pub enum HistoryItem {
    Add(Entry),
    Remove(Entry),
    RemoveMultiple(Vec<Entry>),
    Change(Entry, Entry),
}

pub struct History {
    limit: usize,
    undo_stack: VecDeque<HistoryItem>,
    redo_stack: VecDeque<HistoryItem>,
}

impl History {
    pub fn new(limit: usize) -> Self {
        Self {
            limit,
            undo_stack: VecDeque::new(),
            redo_stack: VecDeque::new(),
        }
    }

    pub fn register(&mut self, item: HistoryItem) {
        if self.limit == 0 {
            return;
        }
        self.redo_stack.clear();
        self.push_undo(item);
    }

    pub fn push_undo(&mut self, item: HistoryItem) {
        if self.limit == 0 {
            return;
        }
        self.undo_stack.push_back(item);
        while self.undo_stack.len() > self.limit {
            self.undo_stack.pop_front();
        }
    }

    pub fn push_redo(&mut self, item: HistoryItem) {
        if self.limit == 0 {
            return;
        }
        self.redo_stack.push_back(item);
        while self.redo_stack.len() > self.limit {
            self.redo_stack.pop_front();
        }
    }

    pub fn pop_undo(&mut self) -> Option<HistoryItem> {
        self.undo_stack.pop_back()
    }

    pub fn pop_redo(&mut self) -> Option<HistoryItem> {
        self.redo_stack.pop_back()
    }
}
