use ratatui::layout::{Constraint, Layout, Rect};
use ratatui::style::Style;
use ratatui::text::{Line, Span};
use unicode_width::UnicodeWidthStr;

/// Centered rectangle using percentages for both dimensions.
pub fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::vertical([
        Constraint::Percentage((100 - percent_y) / 2),
        Constraint::Percentage(percent_y),
        Constraint::Percentage((100 - percent_y) / 2),
    ])
    .split(r);

    Layout::horizontal([
        Constraint::Percentage((100 - percent_x) / 2),
        Constraint::Percentage(percent_x),
        Constraint::Percentage((100 - percent_x) / 2),
    ])
    .split(popup_layout[1])[1]
}

/// Centered rectangle with a percentage width and a fixed height.
pub fn centered_rect_exact_height(percent_x: u16, height: u16, r: Rect) -> Rect {
    let height = height.min(r.height);
    let top = r.height.saturating_sub(height) / 2;
    let popup_layout = Layout::vertical([
        Constraint::Length(top),
        Constraint::Length(height),
        Constraint::Min(0),
    ])
    .split(r);

    Layout::horizontal([
        Constraint::Percentage((100 - percent_x) / 2),
        Constraint::Percentage(percent_x),
        Constraint::Percentage((100 - percent_x) / 2),
    ])
    .split(popup_layout[1])[1]
}

/// Counts the lines produced by a greedy word wrap of `text` into `width`
/// (approximating the paragraph word wrapper).
pub fn wrapped_line_count(text: &str, width: u16) -> u16 {
    if width == 0 {
        return 1;
    }
    let width = width as usize;
    let mut lines: u16 = 0;
    for raw_line in text.split('\n') {
        let mut current: usize = 0;
        let mut count: u16 = 1;
        let mut first_word = true;
        for word in raw_line.split(' ') {
            let w = UnicodeWidthStr::width(word);
            if first_word {
                current = w;
                first_word = false;
                // overlong word
                while current > width {
                    count += 1;
                    current -= width;
                }
                continue;
            }
            if current + 1 + w <= width {
                current += 1 + w;
            } else {
                count += 1;
                current = w;
                while current > width {
                    count += 1;
                    current -= width;
                }
            }
        }
        lines += count;
    }
    lines.max(1)
}

/// Wraps a sequence of spans into lines, moving a span to the next line when
/// it doesn't fit (a span is never split).
pub fn wrap_spans<'a>(spans: Vec<Span<'a>>, max_width: usize) -> Vec<Line<'a>> {
    let mut lines: Vec<Vec<Span<'a>>> = vec![Vec::new()];
    let mut current_width = 0usize;
    for span in spans {
        let w = UnicodeWidthStr::width(span.content.as_ref());
        if current_width + w >= max_width && !(current_width == 0 && false) {
            if current_width + w >= max_width {
                lines.push(Vec::new());
                current_width = 0;
            }
        }
        current_width += w;
        lines.last_mut().unwrap().push(span);
    }
    lines.into_iter().map(Line::from).collect()
}

pub fn styled_line<'a>(text: &'a str, style: Style) -> Line<'a> {
    Line::from(Span::styled(text, style))
}
