use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::layout::Rect;
use ratatui::style::Style;
use ratatui::widgets::{Block, Borders};
use ratatui::Frame;

use crate::textarea::{CursorMove, TextArea};
use crate::themes::Styles;

/// Single line text input built on top of the text area.
pub struct TextInput {
    pub area: TextArea<'static>,
    pub title: String,
    pub error: Option<String>,
}

impl TextInput {
    pub fn new(title: &str, text: &str) -> Self {
        let mut area = TextArea::from_text(text);
        area.cursor_line_style = Style::default();
        Self {
            area,
            title: title.to_string(),
            error: None,
        }
    }

    pub fn new_cursor_end(title: &str, text: &str) -> Self {
        let mut input = Self::new(title, text);
        input.area.move_cursor(CursorMove::End);
        input
    }

    pub fn text(&self) -> String {
        self.area.lines().first().cloned().unwrap_or_default()
    }

    pub fn set_text(&mut self, text: &str) {
        let mut area = TextArea::from_text(text);
        area.cursor_line_style = Style::default();
        area.move_cursor(CursorMove::End);
        self.area = area;
    }

    pub fn is_valid(&self) -> bool {
        self.error.is_none()
    }

    /// Handles a key event; returns true when the content changed.
    pub fn handle_key(&mut self, key: KeyEvent) -> bool {
        handle_textarea_key(&mut self.area, key)
    }

    pub fn render(&mut self, frame: &mut Frame, area: Rect, styles: &Styles, active: bool) {
        let (block_style, cursor_style) = match (self.error.is_some(), active) {
            (true, _) => (
                styles.general.input_block_invalid.style(),
                styles.general.input_corsur_invalid.style(),
            ),
            (false, true) => (
                styles.general.input_block_active.style(),
                styles.general.input_corsur_active.style(),
            ),
            (false, false) => (Style::default(), Style::default()),
        };
        let title = match &self.error {
            Some(err) => format!("{} : {}", self.title, err),
            None => self.title.clone(),
        };
        let block = Block::default()
            .borders(Borders::ALL)
            .style(block_style)
            .title(title);
        self.area.set_block(block);
        self.area.style = Style::default();
        self.area.cursor_style = cursor_style;
        self.area.show_cursor = active;
        frame.render_widget(self.area.widget(), area);
    }
}

/// Default Emacs-like key handling for a text area. Returns true when the key
/// was handled.
pub fn handle_textarea_key(area: &mut TextArea<'_>, key: KeyEvent) -> bool {
    let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
    let alt = key.modifiers.contains(KeyModifiers::ALT);
    let shift = key.modifiers.contains(KeyModifiers::SHIFT);
    match (key.code, ctrl, alt) {
        (KeyCode::Char(c), false, false) => {
            area.insert_char(c);
            true
        }
        (KeyCode::Tab, false, false) => {
            area.insert_tab();
            true
        }
        (KeyCode::Char('h'), true, false) | (KeyCode::Backspace, false, false) => {
            area.delete_char();
            true
        }
        (KeyCode::Char('d'), true, false) | (KeyCode::Delete, false, false) => {
            area.delete_next_char();
            true
        }
        (KeyCode::Char('k'), true, false) => {
            area.delete_line_by_end();
            true
        }
        (KeyCode::Char('j'), true, false) => {
            area.delete_line_by_head();
            true
        }
        (KeyCode::Char('w'), true, false)
        | (KeyCode::Char('h'), false, true)
        | (KeyCode::Backspace, false, true) => {
            area.delete_word();
            true
        }
        (KeyCode::Delete, false, true) | (KeyCode::Char('d'), false, true) => {
            area.delete_next_word();
            true
        }
        (KeyCode::Char('n'), true, false) | (KeyCode::Down, false, false) => {
            area.move_cursor_with_shift(CursorMove::Down, shift);
            true
        }
        (KeyCode::Char('p'), true, false) | (KeyCode::Up, false, false) => {
            area.move_cursor_with_shift(CursorMove::Up, shift);
            true
        }
        (KeyCode::Char('f'), true, false) | (KeyCode::Right, false, false) => {
            area.move_cursor_with_shift(CursorMove::Forward, shift);
            true
        }
        (KeyCode::Char('b'), true, false) | (KeyCode::Left, false, false) => {
            area.move_cursor_with_shift(CursorMove::Back, shift);
            true
        }
        (KeyCode::Char('a'), true, false)
        | (KeyCode::Home, _, _)
        | (KeyCode::Left, true, true)
        | (KeyCode::Char('b'), true, true) => {
            area.move_cursor_with_shift(CursorMove::Head, shift);
            true
        }
        (KeyCode::Char('e'), true, false)
        | (KeyCode::End, _, _)
        | (KeyCode::Right, true, true)
        | (KeyCode::Char('f'), true, true) => {
            area.move_cursor_with_shift(CursorMove::End, shift);
            true
        }
        (KeyCode::Char('<'), false, true)
        | (KeyCode::Up, true, true)
        | (KeyCode::Char('p'), true, true) => {
            area.move_cursor_with_shift(CursorMove::Top, shift);
            true
        }
        (KeyCode::Char('>'), false, true)
        | (KeyCode::Down, true, true)
        | (KeyCode::Char('n'), true, true) => {
            area.move_cursor_with_shift(CursorMove::Bottom, shift);
            true
        }
        (KeyCode::Char('f'), false, true) | (KeyCode::Right, true, false) => {
            area.move_cursor_with_shift(CursorMove::WordForward, shift);
            true
        }
        (KeyCode::Char('b'), false, true) | (KeyCode::Left, true, false) => {
            area.move_cursor_with_shift(CursorMove::WordBack, shift);
            true
        }
        (KeyCode::Char(']'), false, true)
        | (KeyCode::Char('n'), false, true)
        | (KeyCode::Down, true, false) => {
            area.move_cursor_with_shift(CursorMove::ParagraphForward, shift);
            true
        }
        (KeyCode::Char('['), false, true)
        | (KeyCode::Char('p'), false, true)
        | (KeyCode::Up, true, false) => {
            area.move_cursor_with_shift(CursorMove::ParagraphBack, shift);
            true
        }
        (KeyCode::Char('u'), true, false) => {
            area.undo();
            true
        }
        (KeyCode::Char('r'), true, false) => {
            area.redo();
            true
        }
        (KeyCode::Char('y'), true, false) => {
            area.paste();
            true
        }
        (KeyCode::Char('x'), true, false) => {
            area.cut();
            true
        }
        (KeyCode::Char('c'), true, false) => {
            area.copy();
            true
        }
        (KeyCode::Char('v'), true, false) | (KeyCode::PageDown, false, false) => {
            area.scroll_page_down();
            true
        }
        (KeyCode::Char('v'), false, true) | (KeyCode::PageUp, false, false) => {
            area.scroll_page_up();
            true
        }
        (KeyCode::Enter, _, _) => {
            area.insert_newline();
            true
        }
        _ => false,
    }
}
