            area.move_cursor_with_shift(CursorMove::Head, shift);
            true
        }
        (KeyCode::Char('e'), true, false)
        | (KeyCode::End, _, _)
        | (KeyCode::Right, true, true)
        | (KeyCode::Char('f'), true, true) => {
            area.move_cursor_with_shift(CursorMove::End, shift);
            true
        }
        (KeyCode::Char('<'), false, true)
        | (KeyCode::Up, true, true)
        | (KeyCode::Char('p'), true, true) => {
