    }

    pub fn is_insert_mode(&self) -> bool {
        self.mode == EditorMode::Insert
    }

    pub fn set_mode(&mut self, mode: EditorMode) {
        if mode != EditorMode::Visual && self.area.is_selecting() {
            self.area.cancel_selection();
        }
        if mode == EditorMode::Visual && !self.area.is_selecting() {
            self.area.start_selection();
        }
        self.mode = mode;
    }

