    pub fn handle_insert_key(&mut self, key: KeyEvent) -> EditorAction {
        if handle_textarea_key(&mut self.area, key) {
            EditorAction::Handled
        } else {
            EditorAction::None
        }
    }

    /// Handles vim-like keys in normal / visual mode.
    pub fn handle_normal_key(&mut self, key: KeyEvent) -> EditorAction {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        if ctrl {
            return match key.code {
                KeyCode::Char('v') if self.mode == EditorMode::Visual => EditorAction::CopyOsClipboard,
                KeyCode::Char('x') if self.mode == EditorMode::Visual => EditorAction::CutOsClipboard,
                KeyCode::Char('p') => EditorAction::PasteOsClipboard,
                _ => EditorAction::None,
            };
        }
        let visual = self.mode == EditorMode::Visual;
        match key.code {
            KeyCode::Char('h') | KeyCode::Left => {
                self.area.move_cursor(CursorMove::Back);
            }
            KeyCode::Char('l') | KeyCode::Right => {
                self.area.move_cursor(CursorMove::Forward);
            }
