                self.area.move_cursor(CursorMove::End);
            }
            KeyCode::Char('G') => {
                self.area.move_cursor(CursorMove::Bottom);
            }
            KeyCode::PageDown => self.area.scroll_page_down(),
            KeyCode::PageUp => self.area.scroll_page_up(),
            KeyCode::Char('x') => {
                self.area.delete_next_char();
            }
            KeyCode::Char('i') => self.set_mode(EditorMode::Insert),
            KeyCode::Char('a') => {
                self.area.cancel_selection();
                self.area.move_cursor(CursorMove::Forward);
                self.set_mode(EditorMode::Insert);
            }
            KeyCode::Char('A') => {
                self.area.cancel_selection();
                self.area.move_cursor(CursorMove::End);
                self.set_mode(EditorMode::Insert);
            }
            KeyCode::Char('I') => {
                self.area.cancel_selection();
                self.area.move_cursor(CursorMove::Head);
                self.set_mode(EditorMode::Insert);
            }
            KeyCode::Char('o') => {
                self.area.cancel_selection();
                self.area.move_cursor(CursorMove::End);
                self.area.insert_newline();
                self.set_mode(EditorMode::Insert);
            }
            KeyCode::Char('O') => {
                self.area.cancel_selection();
                self.area.move_cursor(CursorMove::Head);
                self.area.insert_newline();
                self.area.move_cursor(CursorMove::Up);
                self.set_mode(EditorMode::Insert);
            }
            KeyCode::Char('d') if visual => {
                self.area.cut();
                self.set_mode(EditorMode::Normal);
            }
            KeyCode::Char('y') if visual => {
                self.area.copy();
                self.set_mode(EditorMode::Normal);
            }
            KeyCode::Char('c') if visual => {
                self.area.cut();
                self.set_mode(EditorMode::Insert);
            }
            _ => return EditorAction::None,
        }
        EditorAction::Handled
    }

    pub fn render(&mut self, frame: &mut Frame, area: Rect, styles: &Styles, active: bool) {
        let mut title = String::from("Content");
        if active {
            title.push_str(" - ");
            title.push_str(self.mode.title());
        }
        if self.is_dirty() {
            title.push_str(" *");
        }
        let (block_style, cursor_style) = if !active {
            (styles.editor.block_normal_inactive.style(), Style::default())
        } else {
            match self.mode {
                EditorMode::Normal => (
                    styles.editor.block_normal_active.style(),
                    styles.editor.cursor_normal.style(),
                ),
                EditorMode::Insert => (
                    styles.editor.block_insert.style(),
                    styles.editor.cursor_insert.style(),
                ),
                EditorMode::Visual => (
                    styles.editor.block_visual.style(),
                    styles.editor.cursor_visual.style(),
                ),
            }
        };
        let block = Block::default()
            .borders(Borders::ALL)
            .style(block_style)
            .title(title);
        self.area.set_block(block);
        self.area.style = Style::default();
        self.area.cursor_style = cursor_style;
        self.area.selection_style = styles.editor.selection_style.style();
        self.area.show_cursor = active;
        frame.render_widget(self.area.widget(), area);
    }
}
