use std::collections::HashSet;

use ratatui::layout::{Alignment, Constraint, Layout, Margin, Rect};
use ratatui::style::{Color, Style};
use ratatui::text::{Line, Span, Text};
use ratatui::widgets::{Block, Borders, List, ListItem, ListState, Paragraph};
use ratatui::Frame;

use crate::app::{format_list_date, App};
use crate::backend::Entry;
use crate::settings::DatumVisibility;
use crate::themes::Styles;

use super::common::wrap_spans;
use super::scrollbar;

/// Palette used for colored tags (ordered by the sorted index of the tag).
const TAG_COLORS: &[(Option<Color>, Color)] = &[
    (Some(Color::Black), Color::LightCyan),
    (Some(Color::Black), Color::LightRed),
    (Some(Color::Black), Color::LightGreen),
    (None, Color::DarkGray),
    (Some(Color::Black), Color::LightYellow),
    (None, Color::Red),
    (Some(Color::Yellow), Color::Blue),
    (Some(Color::Red), Color::Cyan),
    (Some(Color::Black), Color::LightMagenta),
];

pub fn tag_style(tag: &str, all_tags: &[String], colored: bool, styles: &Styles) -> Style {
    if !colored {
        return styles.journals_list.tags_default.style();
    }
    match all_tags.iter().position(|t| t == tag) {
        Some(idx) if idx < TAG_COLORS.len() => {
            let (fg, bg) = TAG_COLORS[idx];
            let mut style = Style::default().bg(bg);
            if let Some(fg) = fg {
                style = style.fg(fg);
            }
            style
        }
        _ => Style::default(),
    }
}

pub struct ListRenderInfo {
    pub title_active: bool,
    pub list_active: bool,
    pub multi_select: Option<HashSet<u32>>,
}

/// Builds the text of a list item for an entry.
pub fn entry_text<'a>(
    entry: &'a Entry,
    wrap_width: usize,
    title_style: Style,
    selected_in_multi: bool,
    all_tags: &[String],
    datum_visibility: DatumVisibility,
    colored_tags: bool,
    styles: &Styles,
) -> Text<'a> {
    let mut lines: Vec<Line<'a>> = Vec::new();

    let title_text = if selected_in_multi {
        format!("* {}", entry.title)
    } else {
        entry.title.clone()
    };
    let title_style = if selected_in_multi {
        styles.journals_list.title_selected.style()
    } else {
        title_style
    };
    for l in crate::wrap::wrap_line(&title_text, wrap_width) {
        lines.push(Line::from(Span::styled(l, title_style)));
    }

    let datum_style = styles.journals_list.date_priority.style();
    match datum_visibility {
        DatumVisibility::Show => {
            let mut text = format_list_date(&entry.date);
            if let Some(p) = entry.priority {
                text.push_str(&format!(" | Priority: {p}"));
            }
            lines.push(Line::from(Span::styled(text, datum_style)));
        }
        DatumVisibility::Hide => {
            if let Some(p) = entry.priority {
                lines.push(Line::from(Span::styled(format!("Priority: {p}"), datum_style)));
            }
        }
        DatumVisibility::EmptyLine => {
            if let Some(p) = entry.priority {
                lines.push(Line::from(Span::styled(format!("Priority: {p}"), datum_style)));
            } else {
                lines.push(Line::from(""));
            }
        }
    }

    if !entry.tags.is_empty() {
        let sep_style = styles.journals_list.tags_default.style();
        let mut spans: Vec<Span<'a>> = Vec::new();
        for (i, tag) in entry.tags.iter().enumerate() {
            if i > 0 {
                spans.push(Span::styled(" | ", sep_style));
            }
            spans.push(Span::styled(
                tag.as_str(),
                tag_style(tag, all_tags, colored_tags, styles),
            ));
        }
        lines.extend(wrap_spans(spans, wrap_width));
    }

    Text::from(lines)
}

pub fn render_journals_list(
    frame: &mut Frame,
    area: Rect,
    app: &App,
    styles: &Styles,
    list_state: &mut ListState,
    info: &ListRenderInfo,
) {
    let visible = app.visible_entries();
    let mut title = String::from("Journals");
    let block_style = if let Some(_) = &info.multi_select {
        title.push_str(" - Multi-Select");
        styles.journals_list.block_multi_select.style()
    } else {
        if app.filter.is_some() {
            title.push_str(" - Filtered");
        }
        if info.list_active {
            styles.journals_list.block_active.style()
        } else {
            styles.journals_list.block_inactive.style()
        }
    };

    let mut block = Block::default()
        .borders(Borders::ALL)
        .border_style(block_style)
        .title_style(block_style)
        .title(title);

    if visible.is_empty() {
        let inner = block.inner(area);
        frame.render_widget(block, area);
        let text_area = inner.inner(Margin::new(1, 1));
