                text.push_str(&format!(" | Priority: {p}"));
            }
            lines.push(Line::from(Span::styled(text, datum_style)));
        }
        DatumVisibility::Hide => {
            if let Some(p) = entry.priority {
                lines.push(Line::from(Span::styled(format!("Priority: {p}"), datum_style)));
            }
        }
        DatumVisibility::EmptyLine => {
            if let Some(p) = entry.priority {
                lines.push(Line::from(Span::styled(format!("Priority: {p}"), datum_style)));
