use chrono::{NaiveDate, Utc};
use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::layout::{Alignment, Constraint, Layout, Rect};
use ratatui::widgets::{Block, Borders, Clear, Paragraph, Wrap};
use ratatui::Frame;

use crate::app::format_input_date;
use crate::backend::{Entry, EntryDraft};
use crate::themes::Styles;

use super::common::{centered_rect_exact_height, wrapped_line_count};
use super::tags_popup::{TagsPopup, TagsPopupResult};
use super::text_input::TextInput;

const FOOTER_TEXT: &str = "Enter or <Ctrl-m>: confirm | Esc or <Ctrl-c>: Cancel | Tab: Change focused control | <Ctrl-Space> or <Ctrl-t>: Open tags";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Field {
    Title,
    Date,
    Priority,
    Tags,
}

impl Field {
    fn next(self) -> Self {
        match self {
            Field::Title => Field::Date,
            Field::Date => Field::Priority,
            Field::Priority => Field::Tags,
            Field::Tags => Field::Title,
        }
    }
}

pub enum EntryPopupResult {
    Open,
    Cancel,
    Confirm(EntryDraft),
}

pub struct EntryPopup {
    pub entry_id: Option<u32>,
    title: TextInput,
    date: TextInput,
    priority: TextInput,
    tags: TextInput,
    active: Field,
    tags_popup: Option<TagsPopup>,
}

pub fn parse_tags(text: &str) -> Vec<String> {
    text.split(',')
        .map(|t| t.trim())
        .filter(|t| !t.is_empty())
        .map(|t| t.to_string())
        .collect()
}

impl EntryPopup {
    pub fn new_create() -> Self {
        let today = Utc::now();
        let today = today
            .date_naive()
            .and_hms_opt(0, 0, 0)
            .unwrap()
            .and_utc();
        Self {
            entry_id: None,
            title: TextInput::new("Title", ""),
            date: TextInput::new("Date", &format_input_date(&today)),
            priority: TextInput::new("Priority", ""),
            tags: TextInput::new("Tags", ""),
            active: Field::Title,
            tags_popup: None,
        }
    }

    pub fn new_edit(entry: &Entry) -> Self {
        Self {
            entry_id: Some(entry.id),
            title: TextInput::new_cursor_end("Title", &entry.title),
            date: TextInput::new("Date", &format_input_date(&entry.date)),
            priority: TextInput::new(
                "Priority",
                &entry.priority.map(|p| p.to_string()).unwrap_or_default(),
            ),
            tags: TextInput::new("Tags", &entry.tags.join(", ")),
            active: Field::Title,
            tags_popup: None,
        }
    }

    pub fn is_edit(&self) -> bool {
        self.entry_id.is_some()
    }

    fn validate_title(&mut self) {
        self.title.error = if self.title.text().is_empty() {
            Some("Title can't be empty".to_string())
        } else {
            None
        };
    }

    fn validate_date(&mut self) {
        self.date.error = match NaiveDate::parse_from_str(&self.date.text(), "%d-%m-%Y") {
            Ok(_) => None,
            Err(err) => Some(err.to_string()),
        };
    }

    fn validate_priority(&mut self) {
        let text = self.priority.text();
        self.priority.error = if text.is_empty() {
            None
        } else {
            match text.parse::<u32>() {
                Ok(_) => None,
                Err(_) => Some("Priority must be a positive number".to_string()),
            }
        };
    }

    fn validate_all(&mut self) -> bool {
        self.validate_title();
        self.validate_date();
        self.validate_priority();
        self.title.is_valid() && self.date.is_valid() && self.priority.is_valid()
    }

    fn validate_active(&mut self) {
        match self.active {
            Field::Title => self.validate_title(),
            Field::Date => self.validate_date(),
            Field::Priority => self.validate_priority(),
            Field::Tags => {}
        }
    }

    fn draft(&self) -> Option<EntryDraft> {
        let date = NaiveDate::parse_from_str(&self.date.text(), "%d-%m-%Y").ok()?;
        let date = date.and_hms_opt(0, 0, 0)?.and_utc();
        let priority = {
            let t = self.priority.text();
            if t.is_empty() {
                None
            } else {
                Some(t.parse::<u32>().ok()?)
            }
        };
        Some(EntryDraft::new(
            date,
            self.title.text(),
            String::new(),
            parse_tags(&self.tags.text()),
            priority,
        ))
    }

    pub fn handle_key(&mut self, key: KeyEvent, all_tags: &[String]) -> EntryPopupResult {
        if let Some(popup) = &mut self.tags_popup {
            match popup.handle_key(key) {
                TagsPopupResult::Open => {}
                TagsPopupResult::Cancel => self.tags_popup = None,
                TagsPopupResult::Confirm(tags) => {
                    self.tags.set_text(&tags.join(", "));
                    self.tags_popup = None;
                }
            }
            return EntryPopupResult::Open;
        }

        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
