use std::collections::HashSet;

use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::layout::{Alignment, Constraint, Layout, Margin, Rect};
use ratatui::style::Style;
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, BorderType, Borders, Clear, List, ListItem, ListState, Paragraph};
use ratatui::Frame;

use crate::themes::Styles;

use super::common::centered_rect;

pub enum TagsPopupResult {
    Open,
    Cancel,
    Confirm(Vec<String>),
}

pub struct TagsPopup {
    pub tags: Vec<String>,
    pub selected: HashSet<String>,
    pub state: ListState,
}

impl TagsPopup {
    /// `current` are the tags currently in the input, `all_tags` the sorted tags
    /// of all journals.
    pub fn new(current: &[String], all_tags: &[String]) -> Self {
        let mut tags: Vec<String> = current
            .iter()
            .filter(|t| !all_tags.contains(t))
            .cloned()
            .collect();
        tags.extend(all_tags.iter().cloned());
        let selected: HashSet<String> = current.iter().cloned().collect();
        let mut state = ListState::default();
        if !tags.is_empty() {
            state.select(Some(0));
        }
        Self {
            tags,
            selected,
            state,
        }
    }

    pub fn handle_key(&mut self, key: KeyEvent) -> TagsPopupResult {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Esc | KeyCode::Char('q') => TagsPopupResult::Cancel,
            KeyCode::Char('c') if ctrl => TagsPopupResult::Cancel,
            KeyCode::Enter => TagsPopupResult::Confirm(
                self.tags
                    .iter()
                    .filter(|t| self.selected.contains(*t))
                    .cloned()
                    .collect(),
            ),
            KeyCode::Char('m') if ctrl => TagsPopupResult::Confirm(
                self.tags
                    .iter()
                    .filter(|t| self.selected.contains(*t))
                    .cloned()
                    .collect(),
            ),
            KeyCode::Char(' ') => {
                if let Some(idx) = self.state.selected() {
                    if let Some(tag) = self.tags.get(idx) {
                        if self.selected.contains(tag) {
                            self.selected.remove(tag);
                        } else {
                            self.selected.insert(tag.clone());
                        }
                    }
                }
                TagsPopupResult::Open
            }
            KeyCode::Char('j') | KeyCode::Down => {
                self.cycle(1);
                TagsPopupResult::Open
            }
            KeyCode::Char('k') | KeyCode::Up => {
                self.cycle(-1);
                TagsPopupResult::Open
            }
            _ => TagsPopupResult::Open,
        }
    }

    fn cycle(&mut self, delta: i32) {
        if self.tags.is_empty() {
            return;
        }
        let len = self.tags.len() as i32;
        let cur = self.state.selected().unwrap_or(0) as i32;
        let next = (cur + delta).rem_euclid(len);
        self.state.select(Some(next as usize));
    }

    pub fn render(&mut self, frame: &mut Frame, area: Rect, styles: &Styles) {
        let popup_area = centered_rect(70, 90, area);
        frame.render_widget(Clear, popup_area);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title("Tags");
        let inner = block.inner(popup_area);
        frame.render_widget(block, popup_area);

        let chunks = Layout::vertical([Constraint::Min(0), Constraint::Length(1)]).split(inner);

        let list_block = Block::default().borders(Borders::BOTTOM);
        if self.tags.is_empty() {
            let list_inner = list_block.inner(chunks[0]);
            frame.render_widget(list_block, chunks[0]);
            let text_area = list_inner.inner(Margin::new(1, 1));
            frame.render_widget(
                Paragraph::new("No journals with tags provided").alignment(Alignment::Center),
                text_area,
            );
        } else {
            let items: Vec<ListItem> = self
                .tags
                .iter()
                .map(|tag| {
                    if self.selected.contains(tag) {
                        ListItem::new(Line::from(Span::styled(
                            format!("* {tag}"),
                            styles.general.list_item_selected.style(),
                        )))
                        .style(styles.general.list_item_selected.style())
                    } else {
                        ListItem::new(Line::from(tag.as_str()))
                    }
                })
                .collect();
            let list = List::new(items)
                .block(list_block)
                .highlight_style(styles.general.list_highlight_active.style())
                .highlight_symbol(">> ");
            frame.render_stateful_widget(list, chunks[0], &mut self.state);
        }

        let footer = Paragraph::new(
            "<Space>: Toggle Selected | Enter or <Ctrl-m>: Confirm | Esc, q or <Ctrl-c>: Cancel",
        )
        .alignment(Alignment::Center)
        .style(Style::default());
        frame.render_widget(footer, chunks[1]);
    }
}
