use std::collections::HashSet;

use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::layout::{Alignment, Constraint, Layout, Rect};
use ratatui::style::Style;
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, BorderType, Borders, Clear, List, ListItem, ListState, Paragraph, Wrap};
use ratatui::Frame;

use crate::app::filter::{Filter, FilterCriterion, FilterMatchLogic};
use crate::themes::Styles;

use super::common::{centered_rect, wrapped_line_count};
use super::text_input::TextInput;

const FOOTER_TEXT: &str = "Tab: Change focused control | Enter or <Ctrl-m>: Confirm | Esc or <Ctrl-c>: Cancel | <Ctrl-r>: Change Matching Logic | <Space>: Tags Toggle Selected";
const NO_TAGS_TEXT: &str = "NO_TAGS (Entries with no tags)";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Field {
    Title,
    Content,
    Priority,
    Tags,
}

impl Field {
    fn next(self) -> Self {
        match self {
            Field::Title => Field::Content,
            Field::Content => Field::Priority,
            Field::Priority => Field::Tags,
            Field::Tags => Field::Title,
        }
    }
}

pub enum FilterPopupResult {
    Open,
    Cancel,
    Confirm(Option<Filter>),
}

pub struct FilterPopup {
    title: TextInput,
    content: TextInput,
    priority: TextInput,
    tags: Vec<String>,
    selected_tags: HashSet<String>,
    no_tags_selected: bool,
    tags_state: ListState,
    logic: FilterMatchLogic,
    active: Field,
}

impl FilterPopup {
    pub fn new(current: Option<&Filter>, all_tags: &[String]) -> Self {
        let (title, content, priority, selected_tags, no_tags, logic) = match current {
            Some(f) => (
                f.title_text(),
                f.content_text(),
                f.priority_text(),
                f.selected_tags().into_iter().collect::<HashSet<_>>(),
                f.no_tags_selected(),
                f.logic,
            ),
            None => (
                String::new(),
                String::new(),
                String::new(),
                HashSet::new(),
                false,
                FilterMatchLogic::default(),
            ),
        };
        let mut tags_state = ListState::default();
        tags_state.select(Some(0));
        Self {
            title: TextInput::new_cursor_end("Title", &title),
            content: TextInput::new_cursor_end("Content", &content),
            priority: TextInput::new_cursor_end("Priority", &priority),
            tags: all_tags.to_vec(),
            selected_tags,
            no_tags_selected: no_tags,
            tags_state,
            logic,
            active: Field::Title,
        }
    }

    fn validate_priority(&mut self) {
        let text = self.priority.text();
        self.priority.error = if text.is_empty() {
            None
        } else {
            match text.parse::<u32>() {
                Ok(_) => None,
                Err(_) => Some("Priority must be a positive number".to_string()),
            }
        };
    }

    fn build_filter(&self) -> Option<Filter> {
        let mut criteria = Vec::new();
        let title = self.title.text();
        if !title.is_empty() {
            criteria.push(FilterCriterion::Title(title));
        }
        let content = self.content.text();
        if !content.is_empty() {
            criteria.push(FilterCriterion::Content(content));
        }
        let priority = self.priority.text();
        if !priority.is_empty() {
            if let Ok(p) = priority.parse::<u32>() {
                criteria.push(FilterCriterion::Priority(p));
            }
        }
        for tag in self.tags.iter() {
            if self.selected_tags.contains(tag) {
                criteria.push(FilterCriterion::Tag(tag.clone()));
            }
        }
        if self.no_tags_selected {
            criteria.push(FilterCriterion::NoTags);
        }
        if criteria.is_empty() {
            None
        } else {
            Some(Filter {
                criteria,
                logic: self.logic,
            })
        }
    }

    fn items_len(&self) -> usize {
        self.tags.len() + 1
    }

    fn cycle(&mut self, delta: i32) {
        let len = self.items_len() as i32;
        let cur = self.tags_state.selected().unwrap_or(0) as i32;
        let next = (cur + delta).rem_euclid(len);
        self.tags_state.select(Some(next as usize));
    }

    fn toggle_selected(&mut self) {
        let Some(idx) = self.tags_state.selected() else {
            return;
        };
        if idx < self.tags.len() {
            let tag = self.tags[idx].clone();
            if self.selected_tags.contains(&tag) {
                self.selected_tags.remove(&tag);
            } else {
                self.selected_tags.insert(tag);
            }
        } else {
            self.no_tags_selected = !self.no_tags_selected;
        }
    }

    pub fn handle_key(&mut self, key: KeyEvent) -> FilterPopupResult {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Esc => return FilterPopupResult::Cancel,
            KeyCode::Char('c') if ctrl => return FilterPopupResult::Cancel,
            KeyCode::Enter => {
                self.validate_priority();
                if self.priority.is_valid() {
                    return FilterPopupResult::Confirm(self.build_filter());
                }
                return FilterPopupResult::Open;
            }
            KeyCode::Char('m') if ctrl => {
                self.validate_priority();
                if self.priority.is_valid() {
                    return FilterPopupResult::Confirm(self.build_filter());
                }
                return FilterPopupResult::Open;
            }
            KeyCode::Tab => {
                self.active = self.active.next();
                return FilterPopupResult::Open;
            }
            KeyCode::Char('r') if ctrl => {
                self.logic.toggle();
                return FilterPopupResult::Open;
            }
            _ => {}
        }

        match self.active {
            Field::Title => {
                self.title.handle_key(key);
            }
            Field::Content => {
                self.content.handle_key(key);
            }
            Field::Priority => {
                if self.priority.handle_key(key) {
                    self.validate_priority();
                }
            }
            Field::Tags => match key.code {
                KeyCode::Char(' ') => self.toggle_selected(),
                KeyCode::Char('j') | KeyCode::Down => self.cycle(1),
                KeyCode::Char('k') | KeyCode::Up => self.cycle(-1),
                _ => {}
            },
        }
        FilterPopupResult::Open
    }

    pub fn render(&mut self, frame: &mut Frame, area: Rect, styles: &Styles) {
        let popup_area = centered_rect(70, 80, area);
        frame.render_widget(Clear, popup_area);
        let block = Block::default().borders(Borders::ALL).title("Filter");
        let inner = block.inner(popup_area);
        frame.render_widget(block, popup_area);

        let footer_lines = wrapped_line_count(FOOTER_TEXT, inner.width.saturating_sub(6));
        let chunks = Layout::vertical([
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Min(0),
            Constraint::Length(footer_lines),
        ])
        .horizontal_margin(3)
        .vertical_margin(1)
        .split(inner);

        let logic_block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title("Matching Logic");
        let logic_inner = logic_block.inner(chunks[0]);
        frame.render_widget(logic_block, chunks[0]);
        frame.render_widget(
            Paragraph::new(self.logic.description()).alignment(Alignment::Center),
            logic_inner,
        );

        self.title
            .render(frame, chunks[1], styles, self.active == Field::Title);
        self.content
            .render(frame, chunks[2], styles, self.active == Field::Content);
        self.priority
            .render(frame, chunks[3], styles, self.active == Field::Priority);

        let tags_active = self.active == Field::Tags;
        let tags_block_style = if tags_active {
            styles.general.input_block_active.style()
        } else {
            Style::default()
        };
        let tags_block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(tags_block_style)
            .title_style(tags_block_style)
            .title("Tags");
        let selected_style = styles.general.list_item_selected.style();
        let mut items: Vec<ListItem> = self
            .tags
