use crate::themes::Styles;

use super::common::{centered_rect, wrapped_line_count};

const FOOTER_TEXT: &str = "Tab: Change focused control | Enter or <Ctrl-m>: Confirm | Esc or <Ctrl-c>: Cancel |<o>: Change Sort Order | <Space>: Move criteria to other list |<j/k> or <up/down> cycle between criteria | <Ctrl-d> Load default";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Focus {
    Available,
    Applied,
}

pub enum SortPopupResult {
    Open,
    Cancel,
    Confirm(Sorter),
}

pub struct SortPopup {
    available: Vec<SortCriteria>,
    applied: Vec<SortCriteria>,
    order: SortOrder,
    available_state: ListState,
    applied_state: ListState,
    focus: Focus,
    applied_invalid: bool,
}

impl SortPopup {
    pub fn new(sorter: &Sorter) -> Self {
        let applied = sorter.criteria.clone();
        let available: Vec<SortCriteria> = SortCriteria::ALL
            .iter()
            .filter(|c| !applied.contains(c))
            .cloned()
            .collect();
        let mut available_state = ListState::default();
        if !available.is_empty() {
            available_state.select(Some(0));
        }
        let mut applied_state = ListState::default();
        if !applied.is_empty() {
            applied_state.select(Some(0));
        }
        Self {
            available,
            applied,
            order: sorter.order,
            available_state,
            applied_state,
            focus: Focus::Available,
            applied_invalid: false,
        }
    }

    fn cycle(&mut self, delta: i32) {
        let (list_len, state) = match self.focus {
            Focus::Available => (self.available.len(), &mut self.available_state),
            Focus::Applied => (self.applied.len(), &mut self.applied_state),
        };
        if list_len == 0 {
            state.select(None);
            return;
        }
        let cur = state.selected().unwrap_or(0) as i32;
        let next = (cur + delta).rem_euclid(list_len as i32);
        state.select(Some(next as usize));
    }

    fn move_selected(&mut self) {
        match self.focus {
            Focus::Available => {
                let Some(idx) = self.available_state.selected() else {
                    return;
                };
                if idx >= self.available.len() {
                    return;
                }
                let item = self.available.remove(idx);
                self.applied.push(item);
                if self.available.is_empty() {
                    self.available_state.select(None);
                } else {
                    self.available_state
                        .select(Some(idx.min(self.available.len() - 1)));
                }
                if self.applied_state.selected().is_none() {
                    self.applied_state.select(Some(0));
                }
            }
            Focus::Applied => {
                let Some(idx) = self.applied_state.selected() else {
                    return;
                };
                if idx >= self.applied.len() {
                    return;
                }
                let item = self.applied.remove(idx);
                self.available.push(item);
                if self.applied.is_empty() {
                    self.applied_state.select(None);
                } else {
                    self.applied_state
                        .select(Some(idx.min(self.applied.len() - 1)));
                }
                if self.available_state.selected().is_none() {
                    self.available_state.select(Some(0));
                }
            }
        }
        self.applied_invalid = self.applied.is_empty();
    }

    fn load_defaults(&mut self) {
        let default = Sorter::default();
        self.applied = default.criteria.clone();
        self.order = default.order;
        self.available = SortCriteria::ALL
            .iter()
            .filter(|c| !self.applied.contains(c))
            .cloned()
            .collect();
        self.available_state
            .select(if self.available.is_empty() { None } else { Some(0) });
        self.applied_state
            .select(if self.applied.is_empty() { None } else { Some(0) });
    }

    pub fn handle_key(&mut self, key: KeyEvent) -> SortPopupResult {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Esc => return SortPopupResult::Cancel,
            KeyCode::Char('c') if ctrl => return SortPopupResult::Cancel,
            KeyCode::Enter => {
                if self.applied.is_empty() {
                    self.applied_invalid = true;
                    return SortPopupResult::Open;
                }
                return SortPopupResult::Confirm(Sorter {
                    criteria: self.applied.clone(),
                    order: self.order,
                });
            }
            KeyCode::Char('m') if ctrl => {
                if self.applied.is_empty() {
                    self.applied_invalid = true;
                    return SortPopupResult::Open;
                }
                return SortPopupResult::Confirm(Sorter {
                    criteria: self.applied.clone(),
                    order: self.order,
                });
            }
            KeyCode::Char('d') if ctrl => self.load_defaults(),
            KeyCode::Tab => {
                self.focus = match self.focus {
                    Focus::Available => Focus::Applied,
                    Focus::Applied => Focus::Available,
                };
            }
            KeyCode::Char('o') => self.order.toggle(),
            KeyCode::Char(' ') => self.move_selected(),
            KeyCode::Char('j') | KeyCode::Down => self.cycle(1),
            KeyCode::Char('k') | KeyCode::Up => self.cycle(-1),
            _ => {}
        }
        SortPopupResult::Open
    }

    pub fn render(&mut self, frame: &mut Frame, area: Rect, styles: &Styles) {
        let popup_area = centered_rect(70, 80, area);
        frame.render_widget(Clear, popup_area);
        let block = Block::default().borders(Borders::ALL).title("Sort");
        let inner = block.inner(popup_area);
        frame.render_widget(block, popup_area);

        let footer_lines = wrapped_line_count(FOOTER_TEXT, inner.width.saturating_sub(6));
        let chunks = Layout::vertical([
