            Constraint::Percentage(50),
            Constraint::Percentage(50),
            Constraint::Length(footer_lines),
        ])
        .horizontal_margin(3)
        .vertical_margin(1)
        .split(inner);

        let order_block = Block::default().borders(Borders::ALL).title("Sort Order");
        let order_inner = order_block.inner(chunks[0]);
        frame.render_widget(order_block, chunks[0]);
        frame.render_widget(
            Paragraph::new(self.order.name()).alignment(Alignment::Center),
            order_inner,
        );

        let active_style = styles.general.input_block_active.style();
        let invalid_style = styles.general.input_block_invalid.style();

        // Available criteria
        let avail_style = if self.focus == Focus::Available {
            active_style
        } else {
            Style::default()
        };
        let avail_block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(avail_style)
            .title_style(avail_style)
            .title("Available Criteria");
        let avail_items: Vec<ListItem> = self
            .available
            .iter()
            .map(|c| ListItem::new(c.name()))
            .collect();
        let avail_highlight = if self.focus == Focus::Available {
            styles.general.list_highlight_active.style()
        } else {
            styles.general.list_highlight_inactive.style()
        };
        let avail_list = List::new(avail_items)
