            .highlight_symbol(">> ");
        frame.render_stateful_widget(avail_list, chunks[1], &mut self.available_state);

        // Applied criteria
        let (applied_style, applied_title) = if self.applied_invalid {
            (invalid_style, "Applied criteria can't be empty")
        } else if self.focus == Focus::Applied {
            (active_style, "Applied Criteria")
        } else {
            (Style::default(), "Applied Criteria")
        };
