            .border_style(applied_style)
            .title_style(applied_style)
            .title(applied_title);
        let applied_items: Vec<ListItem> = self
            .applied
            .iter()
            .map(|c| ListItem::new(c.name()))
            .collect();
        let applied_highlight = if self.focus == Focus::Applied {
