            KeyCode::Char('j') | KeyCode::Down => self.cycle(1),
            KeyCode::Char('k') | KeyCode::Up => self.cycle(-1),
            _ => {}
        }
        SortPopupResult::Open
    }

    pub fn render(&mut self, frame: &mut Frame, area: Rect, styles: &Styles) {
        let popup_area = centered_rect(70, 80, area);
        frame.render_widget(Clear, popup_area);
        let block = Block::default().borders(Borders::ALL).title("Sort");
        let inner = block.inner(popup_area);
        frame.render_widget(block, popup_area);

        let footer_lines = wrapped_line_count(FOOTER_TEXT, inner.width.saturating_sub(6));
        let chunks = Layout::vertical([
            Constraint::Length(3),
            Constraint::Percentage(50),
            Constraint::Percentage(50),
            Constraint::Length(footer_lines),
        ])
        .horizontal_margin(3)
        .vertical_margin(1)
        .split(inner);

        let order_block = Block::default().borders(Borders::ALL).title("Sort Order");
        let order_inner = order_block.inner(chunks[0]);
        frame.render_widget(order_block, chunks[0]);
        frame.render_widget(
            Paragraph::new(self.order.name()).alignment(Alignment::Center),
            order_inner,
        );

        let active_style = styles.general.input_block_active.style();
        let invalid_style = styles.general.input_block_invalid.style();

        // Available criteria
        let avail_style = if self.focus == Focus::Available {
            active_style
        } else {
            Style::default()
        };
        let avail_block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(avail_style)
            .title_style(avail_style)
            .title("Available Criteria");
        let avail_items: Vec<ListItem> = self
            .available
            .iter()
            .map(|c| ListItem::new(c.name()))
            .collect();
        let avail_highlight = if self.focus == Focus::Available {
            styles.general.list_highlight_active.style()
        } else {
            styles.general.list_highlight_inactive.style()
        };
        let avail_list = List::new(avail_items)
            .block(avail_block)
            .highlight_style(avail_highlight)
            .highlight_symbol(">> ");
        frame.render_stateful_widget(avail_list, chunks[1], &mut self.available_state);

        // Applied criteria
        let (applied_style, applied_title) = if self.applied_invalid {
            (invalid_style, "Applied criteria can't be empty")
        } else if self.focus == Focus::Applied {
            (active_style, "Applied Criteria")
        } else {
            (Style::default(), "Applied Criteria")
        };
        let applied_block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(applied_style)
            .title_style(applied_style)
            .title(applied_title);
        let applied_items: Vec<ListItem> = self
            .applied
            .iter()
            .map(|c| ListItem::new(c.name()))
            .collect();
        let applied_highlight = if self.focus == Focus::Applied {
            styles.general.list_highlight_active.style()
        } else {
            styles.general.list_highlight_inactive.style()
        };
        let applied_list = List::new(applied_items)
            .block(applied_block)
            .highlight_style(applied_highlight)
            .highlight_symbol(">> ");
        frame.render_stateful_widget(applied_list, chunks[2], &mut self.applied_state);

        let footer = Paragraph::new(FOOTER_TEXT)
            .alignment(Alignment::Center)
            .wrap(Wrap { trim: true });
        frame.render_widget(footer, chunks[3]);
    }
}
