pub enum FuzzyPopupResult {
    Open,
    Close(Option<u32>),
}

struct MatchItem {
    id: u32,
    title: String,
    indices: Vec<usize>,
    score: i64,
}

pub struct FuzzyPopup {
    query: TextArea<'static>,
    matches: Vec<MatchItem>,
    state: ListState,
}

impl FuzzyPopup {
    pub fn new(app: &App) -> Self {
        let mut query = TextArea::from_text("");
        query.cursor_line_style = Style::default();
        query.cursor_style = Style::default().add_modifier(Modifier::REVERSED);
        let mut popup = Self {
            query,
            matches: Vec::new(),
            state: ListState::default(),
        };
        popup.update_matches(app);
        popup
    }

    fn query_text(&self) -> String {
        self.query.lines().first().cloned().unwrap_or_default()
    }

    fn update_matches(&mut self, app: &App) {
        let query = self.query_text();
        self.matches.clear();
        if query.is_empty() {
            self.state.select(None);
            return;
        }
        // Use a hash map keyed by id to mimic unordered score collection.
        let mut scored: HashMap<u32, MatchItem> = HashMap::new();
        for entry in app.visible_entries() {
            if let Some(m) = fuzzy_match(&entry.title, &query) {
                scored.insert(
                    entry.id,
                    MatchItem {
                        id: entry.id,
                        title: entry.title.clone(),
                        indices: m.indices,
                        score: m.score,
                    },
                );
            }
        }
        let mut items: Vec<MatchItem> = scored.into_values().collect();
        items.sort_by(|a, b| b.score.cmp(&a.score));
        self.matches = items;
        if self.matches.is_empty() {
            self.state.select(None);
        } else {
            self.state.select(Some(0));
        }
    }

    fn cycle(&mut self, delta: i32) {
        if self.matches.is_empty() {
            return;
        }
        let len = self.matches.len() as i32;
        let cur = self.state.selected().unwrap_or(0) as i32;
        let next = (cur + delta).rem_euclid(len);
        self.state.select(Some(next as usize));
    }

    pub fn handle_key(&mut self, key: KeyEvent, app: &App) -> FuzzyPopupResult {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Esc | KeyCode::Enter => {
                let selected = self
                    .state
                    .selected()
                    .and_then(|i| self.matches.get(i))
                    .map(|m| m.id);
                return FuzzyPopupResult::Close(selected);
            }
            KeyCode::Char('c') | KeyCode::Char('m') if ctrl => {
                let selected = self
                    .state
                    .selected()
                    .and_then(|i| self.matches.get(i))
                    .map(|m| m.id);
                return FuzzyPopupResult::Close(selected);
            }
            KeyCode::Down => {
                self.cycle(1);
                return FuzzyPopupResult::Open;
            }
            KeyCode::Up => {
                self.cycle(-1);
                return FuzzyPopupResult::Open;
            }
            KeyCode::Char('n') if ctrl => {
                self.cycle(1);
                return FuzzyPopupResult::Open;
            }
            KeyCode::Char('p') if ctrl => {
                self.cycle(-1);
                return FuzzyPopupResult::Open;
            }
