        let inner = block.inner(popup_area);
        frame.render_widget(block, popup_area);

        let chunks = Layout::vertical([
            Constraint::Length(3),
            Constraint::Min(0),
            Constraint::Length(1),
        ])
        .horizontal_margin(1)
        .vertical_margin(1)
        .split(inner);

        let query_block = Block::default().borders(Borders::ALL).title("Search Query");
        self.query.set_block(query_block);
        self.query.show_cursor = true;
        frame.render_widget(self.query.widget(), chunks[0]);

        let list_block = Block::default()
            .borders(Borders::ALL)
            .title(format!("Entries: {}", self.matches.len()));
        let match_style = Style::default()
            .fg(ratatui::style::Color::LightBlue)
            .add_modifier(Modifier::BOLD);
        let items: Vec<ListItem> = self
            .matches
            .iter()
            .map(|m| {
                let mut spans: Vec<Span> = Vec::new();
                let mut current = String::new();
                let mut current_matched = false;
                for (i, c) in m.title.chars().enumerate() {
                    let matched = m.indices.contains(&i);
                    if matched != current_matched && !current.is_empty() {
                        let style = if current_matched {
                            match_style
                        } else {
                            Style::default()
                        };
                        spans.push(Span::styled(std::mem::take(&mut current), style));
                    }
                    current_matched = matched;
                    current.push(c);
                }
                if !current.is_empty() {
                    let style = if current_matched {
                        match_style
                    } else {
                        Style::default()
                    };
                    spans.push(Span::styled(current, style));
                }
                ListItem::new(Line::from(spans))
            })
            .collect();
        let list = List::new(items)
            .block(list_block)
            .highlight_style(styles.general.list_highlight_active.style())
            .highlight_symbol(">> ");
        frame.render_stateful_widget(list, chunks[1], &mut self.state);

        let footer = Paragraph::new(
            "Esc, Enter, <Ctrl-m>, <Ctrl-c>: Close | Up, Down, <Ctrl-n>, <Ctrl-p>: cycle through filtered list",
        )
        .alignment(Alignment::Center);
        frame.render_widget(footer, chunks[2]);
    }
}
