fn render_table(
    frame: &mut Frame,
    area: Rect,
    title: &str,
    bindings: &[(&str, &str, &str)],
    state: &mut TableState,
) {
    let block = Block::default().borders(Borders::ALL).title(title);
    let inner = block.inner(area);
    let widths = [
        Constraint::Percentage(18),
        Constraint::Percentage(27),
        Constraint::Percentage(55),
    ];
    let col_rects = Layout::horizontal(widths).spacing(1).split(inner);
    let key_w = col_rects[0].width as usize;
    let cmd_w = col_rects[1].width as usize;
    let desc_w = col_rects[2].width as usize;

    let header = Row::new(vec![
        Cell::from("Key"),
        Cell::from("Command"),
        Cell::from("Description"),
    ])
    .style(Style::default().fg(Color::LightBlue))
    .bottom_margin(1);

    let rows: Vec<Row> = bindings
        .iter()
        .map(|(key, cmd, desc)| {
            let key_lines = crate::wrap::wrap_line(key, key_w.max(1));
            let cmd_lines = crate::wrap::wrap_line(cmd, cmd_w.max(1));
            let desc_lines = crate::wrap::wrap_line(desc, desc_w.max(1));
            let height = key_lines.len().max(cmd_lines.len()).max(desc_lines.len()) as u16;
            let key_text = Text::from(
                key_lines
                    .into_iter()
                    .map(|l| Line::from(Span::styled(l, Style::default().add_modifier(Modifier::ITALIC))))
                    .collect::<Vec<_>>(),
            );
            Row::new(vec![
                Cell::from(key_text),
                Cell::from(Text::from(cmd_lines.join("\n"))),
                Cell::from(Text::from(desc_lines.join("\n"))),
            ])
            .height(height)
        })
        .collect();

    let total_height: usize = rows.iter().map(|r| r.height() as usize).sum::<usize>() + 2;
    let count = rows.len();

    let table = Table::new(rows, widths)
        .header(header)
        .block(block)
        .row_highlight_style(Style::default().add_modifier(Modifier::REVERSED));
    frame.render_stateful_widget(table, area, state);

    if total_height > inner.height as usize {
        let scroll_area = area.inner(Margin::new(0, 1));
        scrollbar::render_vertical_scrollbar(
            frame,
            scroll_area,
            count,
            state.selected().unwrap_or(0),
            0,
            Style::default(),
        );
    }
}
