use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::layout::{Alignment, Constraint, Layout, Rect};
use ratatui::style::Style;
use ratatui::widgets::{Block, Borders, Clear, Paragraph, Wrap};
use ratatui::Frame;

use crate::themes::Styles;

use super::common::{centered_rect_exact_height, wrapped_line_count};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MsgBoxKind {
    Error,
    Warning,
    Info,
    Question,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MsgBoxButtons {
    Ok,
    YesNo,
    YesNoCancel,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MsgBoxAnswer {
    Ok,
    Yes,
    No,
    Cancel,
}

pub struct MsgBox {
    pub kind: MsgBoxKind,
    pub buttons: MsgBoxButtons,
    pub text: String,
}

impl MsgBox {
    pub fn info(text: impl Into<String>) -> Self {
        Self {
            kind: MsgBoxKind::Info,
            buttons: MsgBoxButtons::Ok,
            text: text.into(),
        }
    }

    pub fn error(text: impl Into<String>) -> Self {
        Self {
            kind: MsgBoxKind::Error,
            buttons: MsgBoxButtons::Ok,
            text: text.into(),
        }
    }

    pub fn warning(text: impl Into<String>) -> Self {
        Self {
            kind: MsgBoxKind::Warning,
            buttons: MsgBoxButtons::Ok,
            text: text.into(),
        }
    }

    pub fn question(text: impl Into<String>, buttons: MsgBoxButtons) -> Self {
        Self {
            kind: MsgBoxKind::Question,
            buttons,
            text: text.into(),
        }
    }

    /// Handles a key; returns the answer when the box should close.
    pub fn handle_key(&self, key: KeyEvent) -> Option<MsgBoxAnswer> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match self.buttons {
            MsgBoxButtons::Ok => match key.code {
                KeyCode::Char('o') | KeyCode::Enter | KeyCode::Esc => Some(MsgBoxAnswer::Ok),
                KeyCode::Char('c') | KeyCode::Char('m') if ctrl => Some(MsgBoxAnswer::Ok),
                _ => None,
            },
            MsgBoxButtons::YesNo => match key.code {
                KeyCode::Char('y') | KeyCode::Enter => Some(MsgBoxAnswer::Yes),
                KeyCode::Char('m') if ctrl => Some(MsgBoxAnswer::Yes),
                KeyCode::Char('n') | KeyCode::Esc => Some(MsgBoxAnswer::No),
                KeyCode::Char('c') if ctrl => Some(MsgBoxAnswer::No),
                _ => None,
            },
            MsgBoxButtons::YesNoCancel => match key.code {
                KeyCode::Char('y') | KeyCode::Enter => Some(MsgBoxAnswer::Yes),
                KeyCode::Char('m') if ctrl => Some(MsgBoxAnswer::Yes),
                KeyCode::Char('n') => Some(MsgBoxAnswer::No),
                KeyCode::Char('c') if ctrl => Some(MsgBoxAnswer::Cancel),
                KeyCode::Char('c') | KeyCode::Esc => Some(MsgBoxAnswer::Cancel),
                _ => None,
            },
        }
    }

    pub fn render(&self, frame: &mut Frame, area: Rect, styles: &Styles) {
        let width_pct = 55u16;
        let popup_width = (area.width as u32 * width_pct as u32 / 100) as u16;
        let text_lines = wrapped_line_count(&self.text, popup_width.saturating_sub(2));
        let height = 2 + 1 + text_lines + 2 + 1 + 1;
        let popup_area = centered_rect_exact_height(width_pct, height, area);
        frame.render_widget(Clear, popup_area);

        let (color, title) = match self.kind {
            MsgBoxKind::Error => (styles.msgbox.error.0, Some("Error")),
            MsgBoxKind::Warning => (styles.msgbox.warning.0, Some("Warning")),
            MsgBoxKind::Info => (styles.msgbox.info.0, Some("Info")),
            MsgBoxKind::Question => (styles.msgbox.question.0, None),
        };
        let mut block = Block::default()
            .borders(Borders::ALL)
            .border_style(Style::default().fg(color))
            .title_style(Style::default().fg(color));
        if let Some(title) = title {
            block = block.title(title);
        }
        let inner = block.inner(popup_area);
        frame.render_widget(block, popup_area);

        let chunks = Layout::vertical([
            Constraint::Length(1),
            Constraint::Length(text_lines),
            Constraint::Length(2),
            Constraint::Length(1),
            Constraint::Min(0),
        ])
        .split(inner);

        let text = Paragraph::new(self.text.as_str())
            .alignment(Alignment::Center)
            .wrap(Wrap { trim: true });
        frame.render_widget(text, chunks[1]);

        let buttons = match self.buttons {
            MsgBoxButtons::Ok => "(O)k",
            MsgBoxButtons::YesNo => "(Y)es , (N)o",
            MsgBoxButtons::YesNoCancel => "(Y)es , (N)o , (C)ancel",
        };
        frame.render_widget(
            Paragraph::new(buttons).alignment(Alignment::Center),
            chunks[3],
        );
    }
}
