            let height = key_lines.len().max(cmd_lines.len()).max(desc_lines.len()) as u16;
            let key_text = Text::from(
                key_lines
                    .into_iter()
                    .map(|l| Line::from(Span::styled(l, Style::default().add_modifier(Modifier::ITALIC))))
                    .collect::<Vec<_>>(),
            );
            Row::new(vec![
                Cell::from(key_text),
                Cell::from(Text::from(cmd_lines.join("\n"))),
                Cell::from(Text::from(desc_lines.join("\n"))),
            ])
            .height(height)
        })
        .collect();

    let total_height: usize = rows.iter().map(|r| r.height() as usize).sum::<usize>() + 2;
    let count = rows.len();

    let table = Table::new(rows, widths)
        .header(header)
        .block(block)
        .row_highlight_style(Style::default().add_modifier(Modifier::REVERSED));
    frame.render_stateful_widget(table, area, state);

    if total_height > inner.height as usize {
        let scroll_area = area.inner(Margin::new(0, 1));
        scrollbar::render_vertical_scrollbar(
            frame,
            scroll_area,
            count,
            state.selected().unwrap_or(0),
            0,
            Style::default(),
        );
    }
}
