}

type Term = Terminal<CrosstermBackend<io::Stdout>>;

pub struct Ui {
    app: App,
    styles: Styles,
    focus: Focus,
    editor: Editor,
    list_state: ListState,
    multi_select: Option<HashSet<u32>>,
    full_screen: bool,
    popup: Option<Popup>,
    msgbox: Option<(MsgBox, PendingAction)>,
    quit: bool,
    tag_filter_index: Option<usize>,
}

pub fn run(provider: Box<dyn DataProvider>, settings: Settings, styles: Styles) -> Result<()> {
    let mut app = App::new(provider, settings);
    let state = AppState::load(&app.settings.app_state_dir);
    app.sorter = state.sorter.clone();
    app.load_entries()?;

    let mut ui = Ui {
        app,
        styles,
        focus: Focus::JournalsList,
        editor: Editor::new(),
        list_state: ListState::default(),
        multi_select: None,
        full_screen: state.full_screen,
        popup: None,
        msgbox: None,
        quit: false,
        tag_filter_index: None,
    };
    if !ui.app.entries.is_empty() {
        ui.list_state.select(Some(0));
    }
    ui.sync_editor_with_selection();

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;
    terminal.clear()?;

    let result = ui.main_loop(&mut terminal);

    // restore terminal
    let _ = disable_raw_mode();
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
    let _ = terminal.show_cursor();

    result?;

    let state = AppState {
        sorter: ui.app.sorter.clone(),
        full_screen: ui.full_screen,
    };
    if let Err(err) = state.save(&ui.app.settings.app_state_dir) {
        log::error!("Failed to save app state: {err}");
    }
    Ok(())
}

impl Ui {
    fn main_loop(&mut self, terminal: &mut Term) -> Result<()> {
        loop {
            terminal.draw(|frame| self.render(frame))?;
            if event::poll(Duration::from_millis(250))? {
                match event::read()? {
                    Event::Key(key) => {
                        if key.kind == KeyEventKind::Release {
                            continue;
                        }
                        if let Err(err) = self.handle_key(key, terminal) {
                            log::error!("Error while handling key: {err}");
                            self.show_error(format!("{err}"));
                        }
                    }
                    Event::Resize(_, _) => {}
                    _ => {}
                }
            }
            if self.quit {
                return Ok(());
            }
        }
    }

    // ------------------------------------------------------------------
    // Selection helpers
    // ------------------------------------------------------------------

    fn visible_ids(&self) -> Vec<u32> {
        self.app.visible_entries().iter().map(|e| e.id).collect()
    }

    fn selected_id(&self) -> Option<u32> {
        let ids = self.visible_ids();
        let idx = self.list_state.selected()?;
        ids.get(idx).copied()
    }

    fn sync_editor_with_selection(&mut self) {
        let id = self.selected_id();
        match id.and_then(|id| self.app.get_entry(id)) {
            Some(entry) => {
                let content = entry.content.clone();
                self.editor.set_content(&content, true);
            }
            None => self.editor.clear(),
        }
    }

    /// Makes sure the list selection is valid and keeps the current entry
    /// selected when possible.
    fn fix_selection(&mut self, preferred_id: Option<u32>) {
        let ids = self.visible_ids();
        if ids.is_empty() {
            self.list_state.select(None);
            return;
        }
        if let Some(id) = preferred_id {
            if let Some(pos) = ids.iter().position(|i| *i == id) {
                self.list_state.select(Some(pos));
                return;
            }
        }
        let cur = self.list_state.selected().unwrap_or(0);
        self.list_state.select(Some(cur.min(ids.len() - 1)));
    }

    fn select_index(&mut self, idx: usize) {
        let ids = self.visible_ids();
        if ids.is_empty() {
            self.list_state.select(None);
            self.editor.clear();
            return;
        }
        let idx = idx.min(ids.len() - 1);
        self.list_state.select(Some(idx));
        self.sync_editor_with_selection();
    }

    fn select_id(&mut self, id: u32) {
        let ids = self.visible_ids();
        if let Some(pos) = ids.iter().position(|i| *i == id) {
            self.list_state.select(Some(pos));
        }
        self.sync_editor_with_selection();
    }

    // ------------------------------------------------------------------
    // Rendering
    // ------------------------------------------------------------------

    fn footer_text(&self) -> String {
        if self.multi_select.is_some() {
            return "Leave journals multi selection mode: 'q','v','Esc','<Ctrl-c>' | Show help: '?'"
                .to_string();
        }
        match self.focus {
            Focus::Editor if self.editor.is_insert_mode() => {
                "Back to Editor Normal Mode: 'Esc','<Ctrl-c>','<Ctrl-[>' |  Edit using Emacs motions"
                    .to_string()
            }
            Focus::Editor => {
                let mut parts = vec![
                    "Exit: 'q'".to_string(),
                    "Edit journal content: 'Enter','<Ctrl-m>'".to_string(),
                ];
                if self.full_screen {
                    parts.push("Toggle Full Screen Mode: '<Ctrl-f>'".to_string());
                }
                parts.push("Show help: '?'".to_string());
                parts.join(" | ")
            }
            Focus::JournalsList => {
                let mut parts = vec![
                    "Exit: 'q'".to_string(),
                    "Edit journal content: 'Enter','<Ctrl-m>'".to_string(),
                ];
                if self.app.filter.is_some() {
                    parts.push("Reset filter: 'x'".to_string());
                } else {
                    parts.push("Open filter: 'f'".to_string());
                }
                parts.push("Open sort options: 'o'".to_string());
                if self.full_screen {
                    parts.push("Toggle Full Screen Mode: '<Ctrl-f>'".to_string());
                }
                parts.push("Show help: '?'".to_string());
                parts.join(" | ")
            }
        }
    }

    fn render(&mut self, frame: &mut Frame) {
        let area = frame.area();
        let footer_text = self.footer_text();
        let footer_lines = wrapped_line_count(&footer_text, area.width);
        let chunks =
            Layout::vertical([Constraint::Min(0), Constraint::Length(footer_lines)]).split(area);
        let main_area = chunks[0];

        let list_active = self.focus == Focus::JournalsList && self.popup.is_none();
        let editor_active = self.focus == Focus::Editor;

        let info = ListRenderInfo {
            title_active: self.focus == Focus::JournalsList,
            list_active,
            multi_select: self.multi_select.clone(),
        };

        if self.full_screen {
            match self.focus {
                Focus::JournalsList => {
                    render_journals_list(
                        frame,
                        main_area,
                        &self.app,
                        &self.styles,
                        &mut self.list_state,
                        &info,
                    );
                }
                Focus::Editor => {
                    self.editor
                        .render(frame, main_area, &self.styles, editor_active);
                }
            }
        } else {
            let (list_area, editor_area) = split_main(main_area);
            render_journals_list(
                frame,
                list_area,
                &self.app,
                &self.styles,
                &mut self.list_state,
                &info,
            );
            self.editor
                .render(frame, editor_area, &self.styles, editor_active);
        }

        let footer = Paragraph::new(footer_text).wrap(Wrap { trim: true });
        frame.render_widget(footer, chunks[1]);

        if let Some(popup) = &mut self.popup {
            match popup {
                Popup::Help(p) => p.render(frame, area),
                Popup::Entry(p) => p.render(frame, area, &self.styles),
                Popup::Filter(p) => p.render(frame, area, &self.styles),
                Popup::Sort(p) => p.render(frame, area, &self.styles),
                Popup::Fuzzy(p) => p.render(frame, area, &self.styles),
                Popup::Export(p) => p.render(frame, area, &self.styles),
            }
        }

        if let Some((msgbox, _)) = &self.msgbox {
            msgbox.render(frame, area, &self.styles);
        }
    }

    fn show_error(&mut self, text: String) {
        self.msgbox = Some((MsgBox::error(text), PendingAction::None));
    }

    fn show_info(&mut self, text: String) {
        self.msgbox = Some((MsgBox::info(text), PendingAction::None));
    }

    // ------------------------------------------------------------------
    // Key handling
    // ------------------------------------------------------------------

    fn handle_key(&mut self, key: KeyEvent, terminal: &mut Term) -> Result<()> {
        if let Some((msgbox, _)) = &self.msgbox {
            if let Some(answer) = msgbox.handle_key(key) {
                let (msgbox, action) = self.msgbox.take().unwrap();
                self.on_msgbox_answer(msgbox, action, answer, terminal)?;
            }
            return Ok(());
        }

        if self.popup.is_some() {
            return self.handle_popup_key(key, terminal);
        }

        if self.multi_select.is_some() {
            return self.handle_multi_select_key(key);
        }

        match self.focus {
            Focus::Editor if self.editor.is_insert_mode() => self.handle_editor_insert_key(key),
            Focus::Editor => self.handle_editor_normal_key(key, terminal),
            Focus::JournalsList => self.handle_list_key(key, terminal),
        }
    }

    fn handle_popup_key(&mut self, key: KeyEvent, terminal: &mut Term) -> Result<()> {
        let Some(popup) = self.popup.as_mut() else {
            return Ok(());
        };
        match popup {
            Popup::Help(p) => {
                if let HelpPopupResult::Close = p.handle_key(key) {
                    self.popup = None;
                }
            }
            Popup::Entry(p) => {
                let all_tags = self.app.all_tags();
                match p.handle_key(key, &all_tags) {
                    EntryPopupResult::Open => {}
                    EntryPopupResult::Cancel => self.popup = None,
                    EntryPopupResult::Confirm(draft) => {
                        let entry_id = p.entry_id;
                        self.popup = None;
                        self.confirm_entry_popup(entry_id, draft)?;
                    }
                }
            }
            Popup::Filter(p) => match p.handle_key(key) {
                FilterPopupResult::Open => {}
                FilterPopupResult::Cancel => self.popup = None,
                FilterPopupResult::Confirm(filter) => {
                    self.popup = None;
                    self.apply_filter_checked(filter, terminal)?;
                }
            },
            Popup::Sort(p) => match p.handle_key(key) {
                SortPopupResult::Open => {}
                SortPopupResult::Cancel => self.popup = None,
                SortPopupResult::Confirm(sorter) => {
                    self.popup = None;
                    self.apply_sorter(sorter);
                }
            },
            Popup::Fuzzy(p) => match p.handle_key(key, &self.app) {
                FuzzyPopupResult::Open => {}
                FuzzyPopupResult::Close(selected) => {
                    self.popup = None;
                    if let Some(id) = selected {
                        if Some(id) != self.selected_id() {
                            self.run_with_save_check(PendingAction::SelectId(id), terminal)?;
                        }
                    }
                }
            },
            Popup::Export(p) => match p.handle_key(key) {
                ExportPopupResult::Open => {}
                ExportPopupResult::Cancel => self.popup = None,
                ExportPopupResult::Confirm(path) => {
                    let kind = std::mem::replace(
                        &mut p.kind,
                        ExportKind::Journals { ids: Vec::new() },
                    );
                    self.popup = None;
                    self.do_export(kind, path)?;
                }
            },
        }
        Ok(())
    }

    fn confirm_entry_popup(&mut self, entry_id: Option<u32>, draft: EntryDraft) -> Result<()> {
        match entry_id {
            None => {
                let entry = self.app.add_entry(draft)?;
                self.fix_selection(Some(entry.id));
                self.sync_editor_with_selection();
            }
            Some(id) => {
                if let Some(mut entry) = self.app.get_entry(id).cloned() {
                    entry.title = draft.title;
                    entry.date = draft.date;
                    entry.tags = draft.tags;
                    entry.priority = draft.priority;
                    self.app.update_entry(entry)?;
                    self.fix_selection(Some(id));
                }
            }
        }
        Ok(())
    }

    fn apply_sorter(&mut self, sorter: Sorter) {
        let selected = self.selected_id();
        self.app.sorter = sorter;
        self.app.sort_entries();
        self.fix_selection(selected);
    }

    fn apply_filter_checked(&mut self, filter: Option<Filter>, terminal: &mut Term) -> Result<()> {
        // If the current entry is still visible after filtering nothing changes
        // for the editor; otherwise check for unsaved changes.
        let selected = self.selected_id();
        let still_visible = match (&filter, selected) {
            (Some(f), Some(id)) => self
                .app
                .get_entry(id)
                .map(|e| f.check_entry(e))
                .unwrap_or(false),
            (None, _) => true,
            (Some(_), None) => true,
        };
        if still_visible || !self.editor.is_dirty() {
            self.apply_filter(filter);
            Ok(())
        } else {
            self.run_with_save_check(PendingAction::ApplyFilter(filter), terminal)
        }
    }

    fn apply_filter(&mut self, filter: Option<Filter>) {
        let selected = self.selected_id();
        self.app.filter = filter;
        self.tag_filter_index = None;
        let ids = self.visible_ids();
        match selected.and_then(|id| ids.iter().position(|i| *i == id)) {
            Some(pos) => self.list_state.select(Some(pos)),
            None => {
                if ids.is_empty() {
                    self.list_state.select(None);
                } else {
                    self.list_state.select(Some(0));
                }
                self.sync_editor_with_selection();
            }
        }
    }

    fn cycle_tag_filter(&mut self) {
        let tags = self.app.all_tags();
        if tags.is_empty() {
            return;
        }
        let next = match self.tag_filter_index {
            None => 0,
            Some(i) => (i + 1) % tags.len(),
        };
        let filter = Filter {
            criteria: vec![FilterCriterion::Tag(tags[next].clone())],
            logic: FilterMatchLogic::All,
        };
        self.apply_filter(Some(filter));
        self.tag_filter_index = Some(next);
    }

    fn do_export(&mut self, kind: ExportKind, path: PathBuf) -> Result<()> {
        match kind {
            ExportKind::Content { entry_id, .. } => {
                let content = if Some(entry_id) == self.selected_id() {
                    self.editor.content()
                } else {
                    self.app
                        .get_entry(entry_id)
                        .map(|e| e.content.clone())
                        .unwrap_or_default()
                };
                if let Some(parent) = path.parent() {
                    if !parent.as_os_str().is_empty() && !parent.exists() {
                        std::fs::create_dir_all(parent)?;
                    }
                }
                match std::fs::write(&path, content) {
                    Ok(()) => {
                        if self.app.settings.export.show_confirmation {
                            self.show_info(format!(
                                "Journal content exported to file {}",
                                path.display()
                            ));
                        }
                    }
                    Err(err) => {
                        self.show_error(format!(
                            "Error while exporting journal content to file {}. Error: {err}",
                            path.display()
                        ));
                    }
                }
            }
            ExportKind::Journals { ids } => {
                let drafts: Vec<EntryDraft> = self
                    .app
                    .entries
                    .iter()
                    .filter(|e| ids.contains(&e.id))
                    .map(EntryDraft::from_entry)
                    .collect();
                let dto = EntriesDTO::new(drafts);
                match dto.write_to_file(&path) {
                    Ok(()) => {
                        if self.app.settings.export.show_confirmation {
                            self.show_info(format!(
                                "Journal(s)  exported to file {}",
                                path.display()
                            ));
                        }
                    }
                    Err(err) => {
                        self.show_error(format!(
                            "Error while exporting journals to file {}. Error: {err}",
                            path.display()
                        ));
                    }
                }
            }
        }
        Ok(())
    }

    fn export_default_dir(&self) -> PathBuf {
        match &self.app.settings.export.default_path {
            Some(p) => p.clone(),
            None => std::env::current_dir().unwrap_or_default(),
        }
    }

    fn open_export_content(&mut self) {
        let Some(id) = self.selected_id() else {
            return;
        };
        let Some(entry) = self.app.get_entry(id) else {
            return;
        };
        let title = entry.title.clone();
        let file_name = format!("{}.txt", title);
        let path = self.export_default_dir().join(file_name);
        self.popup = Some(Popup::Export(ExportPopup::new(
            ExportKind::Content {
                entry_id: id,
                title,
            },
            path,
        )));
    }

    fn open_export_journals(&mut self, ids: Vec<u32>) {
        let path = self.export_default_dir().join("tjournal_export.json");
        self.popup = Some(Popup::Export(ExportPopup::new(
            ExportKind::Journals { ids },
            path,
        )));
    }

    // ------------------------------------------------------------------
    // Save / discard / pending actions
    // ------------------------------------------------------------------

    fn save_current(&mut self) -> Result<()> {
        if !self.editor.is_dirty() {
            return Ok(());
        }
        let Some(id) = self.selected_id() else {
            return Ok(());
        };
        if let Some(mut entry) = self.app.get_entry(id).cloned() {
            entry.content = self.editor.content();
            self.app.update_entry(entry)?;
            self.editor.mark_saved();
            self.fix_selection(Some(id));
        }
        Ok(())
    }

    fn discard_changes(&mut self) {
        let mode = self.editor.mode;
        self.sync_editor_with_selection();
        self.editor.set_mode(mode);
    }

    /// Runs the action, asking to save unsaved changes first when needed.
    fn run_with_save_check(&mut self, action: PendingAction, terminal: &mut Term) -> Result<()> {
        if self.editor.is_dirty() {
            self.msgbox = Some((
                MsgBox::question(
                    "Do you want to save the changes on the current journal?",
                    MsgBoxButtons::YesNoCancel,
                ),
                action,
            ));
            Ok(())
        } else {
            self.run_action(action, terminal)
        }
    }

    fn run_action(&mut self, action: PendingAction, terminal: &mut Term) -> Result<()> {
        match action {
            PendingAction::None => {}
            PendingAction::Quit => self.quit = true,
            PendingAction::SelectIndex(idx) => self.select_index(idx),
            PendingAction::SelectId(id) => self.select_id(id),
            PendingAction::Undo => {
                let select = self.app.undo()?;
                self.after_history_change(select);
            }
            PendingAction::Redo => {
                let select = self.app.redo()?;
                self.after_history_change(select);
            }
            PendingAction::Reload => {
                let selected = self.selected_id();
                self.app.load_entries()?;
                self.fix_selection(selected);
                self.sync_editor_with_selection();
            }
            PendingAction::OpenCreate => {
                self.popup = Some(Popup::Entry(EntryPopup::new_create()));
            }
            PendingAction::DeleteEntry(id) => {
                self.app.remove_entry(id)?;
                self.select_index(0);
            }
            PendingAction::DeleteMultiple(ids) => {
                self.app.remove_entries(&ids)?;
                if let Some(set) = &mut self.multi_select {
                    set.clear();
                }
                self.select_index(0);
            }
            PendingAction::DiscardChanges => self.discard_changes(),
            PendingAction::ExternalEditor => self.run_external_editor(terminal)?,
            PendingAction::CycleTagFilter => self.cycle_tag_filter(),
            PendingAction::ApplyFilter(filter) => self.apply_filter(filter),
        }
        Ok(())
    }

    fn after_history_change(&mut self, select: Option<u32>) {
        let current = self.selected_id();
        let preferred = select.or(current);
        self.fix_selection(preferred);
        self.sync_editor_with_selection();
    }

    fn on_msgbox_answer(
        &mut self,
        msgbox: MsgBox,
        action: PendingAction,
        answer: MsgBoxAnswer,
        terminal: &mut Term,
    ) -> Result<()> {
        match msgbox.buttons {
            MsgBoxButtons::YesNoCancel => match answer {
                MsgBoxAnswer::Yes => {
                    self.save_current()?;
                    self.run_action(action, terminal)
                }
                MsgBoxAnswer::No => {
                    self.discard_changes();
                    self.run_action(action, terminal)
                }
                _ => Ok(()),
            },
            MsgBoxButtons::YesNo => match answer {
                MsgBoxAnswer::Yes => self.run_action(action, terminal),
                _ => Ok(()),
            },
            MsgBoxButtons::Ok => self.run_action(action, terminal),
        }
    }

    // ------------------------------------------------------------------
    // External editor & clipboard
    // ------------------------------------------------------------------

    fn run_external_editor(&mut self, terminal: &mut Term) -> Result<()> {
        if self.selected_id().is_none() {
            return Ok(());
        }
        let command = self
            .app
            .settings
            .external_editor
            .command
            .clone()
            .filter(|c| !c.trim().is_empty())
            .or_else(|| std::env::var("VISUAL").ok().filter(|c| !c.trim().is_empty()))
            .or_else(|| std::env::var("EDITOR").ok().filter(|c| !c.trim().is_empty()))
            .unwrap_or_else(|| "vi".to_string());

        let ext = &self.app.settings.external_editor.temp_file_extension;
        let temp_path = std::env::temp_dir().join(format!("tui_journal.{ext}"));
        let content = self.editor.content();
        std::fs::write(&temp_path, &content)
            .with_context(|| format!("Failed to write temp file {}", temp_path.display()))?;

        let mut parts = command.split_whitespace();
        let program = parts.next().unwrap_or("vi").to_string();
        let args: Vec<String> = parts.map(|s| s.to_string()).collect();

        // leave the TUI
        let _ = disable_raw_mode();
        let _ = execute!(io::stdout(), LeaveAlternateScreen);
        let _ = terminal.show_cursor();

        let status = std::process::Command::new(&program)
            .args(&args)
            .arg(&temp_path)
            .status();

        // return to the TUI
        let _ = enable_raw_mode();
        let _ = execute!(io::stdout(), EnterAlternateScreen);
        let _ = terminal.clear();

        match status {
            Ok(_) => {
                let new_content = std::fs::read_to_string(&temp_path).unwrap_or(content);
                let new_content = new_content.replace("\r\n", "\n");
                let mode = self.editor.mode;
                let saved = self.editor.saved_content.clone();
                let mut area = crate::textarea::TextArea::from_text(&new_content);
                area.cursor_line_style = ratatui::style::Style::default();
                area.move_cursor(crate::textarea::CursorMove::Bottom);
                area.move_cursor(crate::textarea::CursorMove::End);
                self.editor.area = area;
                self.editor.saved_content = saved;
                self.editor.set_mode(if mode == EditorMode::Visual {
                    EditorMode::Normal
                } else {
                    mode
                });
                if self.app.settings.external_editor.auto_save {
                    self.save_current()?;
                }
            }
            Err(err) => {
                self.show_error(format!(
                    "Error while opening the editor. Editor command: '{command}'. Error: {err}"
                ));
            }
        }
        let _ = std::fs::remove_file(&temp_path);
        Ok(())
    }

    fn clipboard_error(&mut self, err: String) {
        self.show_error(format!(
            "Error while communicating with the operation system clipboard.Error Details: {err}"
        ));
    }

    fn copy_to_os_clipboard(&mut self, text: &str) -> Result<(), String> {
        clipboard::set_text(text)
    }

    fn handle_editor_action(&mut self, action: EditorAction) -> Result<()> {
        match action {
            EditorAction::CopyOsClipboard => {
                if let Some(text) = self.editor.area.selected_text() {
                    match self.copy_to_os_clipboard(&text) {
                        Ok(()) => {
                            self.editor.area.copy();
                            self.editor.set_mode(EditorMode::Normal);
                        }
                        Err(err) => self.clipboard_error(err),
                    }
                }
            }
            EditorAction::CutOsClipboard => {
                if let Some(text) = self.editor.area.selected_text() {
                    match self.copy_to_os_clipboard(&text) {
                        Ok(()) => {
                            self.editor.area.cut();
                            self.editor.set_mode(EditorMode::Normal);
                        }
                        Err(err) => self.clipboard_error(err),
                    }
                }
            }
            EditorAction::PasteOsClipboard => match clipboard::get_text() {
                Ok(text) => {
                    self.editor.area.insert_str(text);
                }
                Err(err) => self.clipboard_error(err),
            },
            _ => {}
        }
        Ok(())
    }

    // ------------------------------------------------------------------
    // Editor keys
    // ------------------------------------------------------------------

    fn handle_editor_insert_key(&mut self, key: KeyEvent) -> Result<()> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Esc => {
                self.editor.set_mode(EditorMode::Normal);
                return Ok(());
            }
            KeyCode::Char('c') | KeyCode::Char('[') if ctrl => {
                self.editor.set_mode(EditorMode::Normal);
                return Ok(());
            }
            KeyCode::Char('s') if ctrl => {
                self.save_current()?;
                return Ok(());
            }
            KeyCode::Char('q') if ctrl => {
                self.ask_discard();
                return Ok(());
            }
            KeyCode::Char('p') if ctrl => {
                return self.handle_editor_action(EditorAction::PasteOsClipboard);
            }
            _ => {}
        }
        let action = self.editor.handle_insert_key(key);
        if self.app.settings.sync_os_clipboard {
            if ctrl && matches!(key.code, KeyCode::Char('x') | KeyCode::Char('c')) {
                let yank = self.editor.area.yank_text();
                let _ = clipboard::set_text(&yank);
            }
        }
        let _ = action;
        Ok(())
    }

    fn ask_discard(&mut self) {
        if self.editor.is_dirty() {
            self.msgbox = Some((
                MsgBox::question(
                    "Do you want to discard all unsaved changes?",
                    MsgBoxButtons::YesNo,
                ),
                PendingAction::DiscardChanges,
            ));
        }
    }

    fn handle_editor_normal_key(&mut self, key: KeyEvent, terminal: &mut Term) -> Result<()> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let visual = self.editor.mode == EditorMode::Visual;

        // Mode switching keys first
        match key.code {
            KeyCode::Esc => {
                self.editor.set_mode(EditorMode::Normal);
                return Ok(());
            }
            KeyCode::Char('c') | KeyCode::Char('[') if ctrl => {
                self.editor.set_mode(EditorMode::Normal);
                return Ok(());
            }
            KeyCode::Char('v') if !ctrl => {
                if visual {
                    self.editor.set_mode(EditorMode::Normal);
                } else {
                    self.editor.set_mode(EditorMode::Visual);
                }
                return Ok(());
            }
            KeyCode::Enter => {
                self.editor.set_mode(EditorMode::Insert);
                return Ok(());
            }
            KeyCode::Char('m') if ctrl => {
                self.editor.set_mode(EditorMode::Insert);
                return Ok(());
            }
            _ => {}
        }

        // Editor (vim-like) keys
        let action = self.editor.handle_normal_key(key);
        match action {
            EditorAction::Handled => {
                if self.app.settings.sync_os_clipboard
                    && visual
                    && matches!(key.code, KeyCode::Char('y') | KeyCode::Char('d') | KeyCode::Char('c'))
                {
                    let yank = self.editor.area.yank_text();
                    let _ = clipboard::set_text(&yank);
                }
                return Ok(());
            }
            EditorAction::None => {}
            other => return self.handle_editor_action(other),
        }

        // Global keys available in editor normal mode
        match key.code {
            KeyCode::Char('q') if !ctrl => self.run_with_save_check(PendingAction::Quit, terminal)?,
            KeyCode::Char('q') if ctrl => self.ask_discard(),
            KeyCode::Char('?') => self.popup = Some(Popup::Help(HelpPopup::new())),
            KeyCode::Tab | KeyCode::BackTab => self.focus = Focus::JournalsList,
            KeyCode::Char('l') | KeyCode::Char('h') if ctrl => self.focus = Focus::JournalsList,
            KeyCode::Char('s') => self.save_current()?,
            KeyCode::Char('r') if ctrl => {
                self.run_with_save_check(PendingAction::Reload, terminal)?
            }
            KeyCode::Char('>') => self.open_export_content(),
            KeyCode::Char('y') => {
                self.run_external_editor(terminal)?;
            }
            KeyCode::Char('f') if ctrl => {
                self.full_screen = !self.full_screen;
            }
            KeyCode::Char('u') if !ctrl => {
                self.run_with_save_check(PendingAction::Undo, terminal)?
            }
            KeyCode::Char('U') => self.run_with_save_check(PendingAction::Redo, terminal)?,
            _ => {}
        }
        Ok(())
    }

    // ------------------------------------------------------------------
    // Journals list keys
    // ------------------------------------------------------------------

    fn handle_list_key(&mut self, key: KeyEvent, terminal: &mut Term) -> Result<()> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let count = self.visible_ids().len();
        let selected = self.list_state.selected();
        match key.code {
            KeyCode::Char('q') if !ctrl => {
                self.run_with_save_check(PendingAction::Quit, terminal)?
            }
            KeyCode::Char('?') => self.popup = Some(Popup::Help(HelpPopup::new())),
            KeyCode::Tab | KeyCode::BackTab => {
                if count > 0 || true {
                    self.focus = Focus::Editor;
                }
            }
            KeyCode::Char('l') | KeyCode::Char('h') if ctrl => self.focus = Focus::Editor,
            KeyCode::Down | KeyCode::Char('j') => {
                if let Some(idx) = selected {
                    if idx + 1 < count {
                        self.run_with_save_check(PendingAction::SelectIndex(idx + 1), terminal)?;
                    }
                }
            }
            KeyCode::Up | KeyCode::Char('k') => {
                if let Some(idx) = selected {
                    if idx > 0 {
                        self.run_with_save_check(PendingAction::SelectIndex(idx - 1), terminal)?;
                    }
                }
            }
            KeyCode::Home => {
                if let Some(idx) = selected {
                    if idx != 0 {
                        self.run_with_save_check(PendingAction::SelectIndex(0), terminal)?;
                    }
                }
            }
            KeyCode::End => {
                if let Some(idx) = selected {
                    if count > 0 && idx != count - 1 {
                        self.run_with_save_check(PendingAction::SelectIndex(count - 1), terminal)?;
                    }
                }
            }
            KeyCode::PageUp => {
                if let Some(idx) = selected {
                    let page = self.app.settings.scroll_per_page.max(1);
                    let target = idx.saturating_sub(page);
                    if target != idx {
                        self.run_with_save_check(PendingAction::SelectIndex(target), terminal)?;
                    }
                }
            }
            KeyCode::PageDown => {
                if let Some(idx) = selected {
                    let page = self.app.settings.scroll_per_page.max(1);
                    let target = (idx + page).min(count.saturating_sub(1));
                    if target != idx {
                        self.run_with_save_check(PendingAction::SelectIndex(target), terminal)?;
                    }
                }
            }
            KeyCode::Char('n') if !ctrl => {
                self.run_with_save_check(PendingAction::OpenCreate, terminal)?
            }
            KeyCode::Char('e') if !ctrl => {
                if let Some(entry) = self.selected_id().and_then(|id| self.app.get_entry(id)) {
                    self.popup = Some(Popup::Entry(EntryPopup::new_edit(entry)));
                }
            }
            KeyCode::Delete => self.ask_delete_current(),
            KeyCode::Char('d') => self.ask_delete_current(),
            KeyCode::Enter => {
                if count > 0 || true {
                    self.focus = Focus::Editor;
                    self.editor.set_mode(EditorMode::Insert);
                }
            }
            KeyCode::Char('m') if ctrl => {
                self.focus = Focus::Editor;
                self.editor.set_mode(EditorMode::Insert);
            }
            KeyCode::Char('s') => self.save_current()?,
            KeyCode::Char('q') if ctrl => self.ask_discard(),
            KeyCode::Char('r') if ctrl => {
                self.run_with_save_check(PendingAction::Reload, terminal)?
            }
            KeyCode::Char('>') => self.open_export_content(),
            KeyCode::Char('y') => self.run_external_editor(terminal)?,
            KeyCode::Char('v') if !ctrl => {
                if count > 0 {
                    self.multi_select = Some(HashSet::new());
                }
            }
            KeyCode::Char('f') if !ctrl => {
                let all_tags = self.app.all_tags();
                self.popup = Some(Popup::Filter(FilterPopup::new(
                    self.app.filter.as_ref(),
                    &all_tags,
                )));
            }
            KeyCode::Char('f') if ctrl => self.full_screen = !self.full_screen,
            KeyCode::Char('x') => {
                if self.app.filter.is_some() {
                    self.apply_filter_checked(None, terminal)?;
                }
            }
            KeyCode::Char('t') if ctrl => {
                self.cycle_tag_filter_checked(terminal)?;
            }
            KeyCode::Char('a') | KeyCode::Char('F') => {
                self.popup = Some(Popup::Fuzzy(FuzzyPopup::new(&self.app)));
            }
            KeyCode::Char('o') => {
                self.popup = Some(Popup::Sort(SortPopup::new(&self.app.sorter)));
            }
            KeyCode::Char('u') if !ctrl => {
                self.run_with_save_check(PendingAction::Undo, terminal)?
            }
            KeyCode::Char('U') => self.run_with_save_check(PendingAction::Redo, terminal)?,
            _ => {}
        }
        Ok(())
    }

    fn cycle_tag_filter_checked(&mut self, terminal: &mut Term) -> Result<()> {
        let tags = self.app.all_tags();
        if tags.is_empty() {
            return Ok(());
        }
        let next = match self.tag_filter_index {
            None => 0,
            Some(i) => (i + 1) % tags.len(),
        };
        let still_visible = self
            .selected_id()
            .and_then(|id| self.app.get_entry(id))
            .map(|e| e.tags.iter().any(|t| *t == tags[next]))
            .unwrap_or(true);
        if still_visible || !self.editor.is_dirty() {
            self.cycle_tag_filter();
            Ok(())
        } else {
            self.run_with_save_check(PendingAction::CycleTagFilter, terminal)
        }
    }

    fn ask_delete_current(&mut self) {
        if let Some(id) = self.selected_id() {
            self.msgbox = Some((
                MsgBox::question(
                    "Do you want to remove the current journal?",
                    MsgBoxButtons::YesNo,
                ),
                PendingAction::DeleteEntry(id),
            ));
        }
    }

    // ------------------------------------------------------------------
    // Multi select keys
    // ------------------------------------------------------------------

    fn handle_multi_select_key(&mut self, key: KeyEvent) -> Result<()> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let ids = self.visible_ids();
        let count = ids.len();
        let selected = self.list_state.selected();
        match key.code {
            KeyCode::Char('?') => self.popup = Some(Popup::Help(HelpPopup::new())),
            KeyCode::Down | KeyCode::Char('j') => {
                if let Some(idx) = selected {
                    if idx + 1 < count {
                        self.select_index(idx + 1);
                    }
                }
            }
            KeyCode::Up | KeyCode::Char('k') => {
                if let Some(idx) = selected {
                    if idx > 0 {
                        self.select_index(idx - 1);
                    }
                }
            }
            KeyCode::Home => self.select_index(0),
            KeyCode::End => {
                if count > 0 {
                    self.select_index(count - 1);
                }
            }
            KeyCode::Char('q') | KeyCode::Char('v') | KeyCode::Esc => self.multi_select = None,
            KeyCode::Char('c') if ctrl => self.multi_select = None,
            KeyCode::Char(' ') | KeyCode::Enter => {
                if let Some(id) = self.selected_id() {
                    if let Some(set) = &mut self.multi_select {
                        if set.contains(&id) {
                            set.remove(&id);
                        } else {
                            set.insert(id);
                        }
                    }
                }
            }
            KeyCode::Char('m') if ctrl => {
                if let Some(id) = self.selected_id() {
                    if let Some(set) = &mut self.multi_select {
                        if set.contains(&id) {
                            set.remove(&id);
                        } else {
                            set.insert(id);
                        }
                    }
                }
            }
            KeyCode::Char('a') => {
                if let Some(set) = &mut self.multi_select {
                    set.extend(ids.iter().copied());
                }
            }
            KeyCode::Char('x') => {
                if let Some(set) = &mut self.multi_select {
                    set.clear();
                }
            }
            KeyCode::Char('i') => {
                if let Some(set) = &mut self.multi_select {
                    let new: HashSet<u32> = ids
                        .iter()
                        .copied()
                        .filter(|id| !set.contains(id))
                        .collect();
                    *set = new;
                }
            }
            KeyCode::Char('d') | KeyCode::Delete => {
                if let Some(set) = &self.multi_select {
                    if !set.is_empty() {
                        let mut to_delete: Vec<u32> =
                            ids.iter().copied().filter(|id| set.contains(id)).collect();
                        to_delete.sort();
                        let count = to_delete.len();
                        self.msgbox = Some((
                            MsgBox::question(
                                format!("Do you want to remove the selected {count} journals?"),
                                MsgBoxButtons::YesNo,
                            ),
                            PendingAction::DeleteMultiple(to_delete),
                        ));
                    }
                }
            }
            KeyCode::Char('>') => {
                if let Some(set) = &self.multi_select {
                    if !set.is_empty() {
                        let to_export: Vec<u32> =
                            ids.iter().copied().filter(|id| set.contains(id)).collect();
                        self.open_export_journals(to_export);
                    }
                }
            }
            _ => {}
        }
        Ok(())
    }
}

mod clipboard {
    use std::io::Write;
    use std::process::{Command, Stdio};

    const UNREACHABLE: &str =
        "Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable";

    fn has_display() -> bool {
        std::env::var_os("DISPLAY").is_some() || std::env::var_os("WAYLAND_DISPLAY").is_some()
    }

    fn tool_available(name: &str) -> bool {
        Command::new("which")
            .arg(name)
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status()
            .map(|s| s.success())
            .unwrap_or(false)
    }

    pub fn set_text(text: &str) -> Result<(), String> {
        if !has_display() {
            return Err(UNREACHABLE.to_string());
        }
        let candidates: [(&str, &[&str]); 3] = [
            ("wl-copy", &[]),
            ("xclip", &["-selection", "clipboard"]),
            ("xsel", &["--clipboard", "--input"]),
        ];
        for (tool, args) in candidates.iter() {
            if !tool_available(tool) {
                continue;
            }
            let mut child = Command::new(tool)
                .args(*args)
                .stdin(Stdio::piped())
                .stdout(Stdio::null())
                .stderr(Stdio::null())
                .spawn()
                .map_err(|e| format!("Unknown error while interacting with the clipboard: {e}"))?;
            if let Some(stdin) = child.stdin.as_mut() {
                let _ = stdin.write_all(text.as_bytes());
            }
            let _ = child.wait();
            return Ok(());
        }
        Err(UNREACHABLE.to_string())
    }

    pub fn get_text() -> Result<String, String> {
        if !has_display() {
            return Err(UNREACHABLE.to_string());
        }
        let candidates: [(&str, &[&str]); 3] = [
            ("wl-paste", &["--no-newline"]),
            ("xclip", &["-selection", "clipboard", "-o"]),
            ("xsel", &["--clipboard", "--output"]),
        ];
        for (tool, args) in candidates.iter() {
            if !tool_available(tool) {
                continue;
            }
            let output = Command::new(tool)
                .args(*args)
                .output()
                .map_err(|e| format!("Unknown error while interacting with the clipboard: {e}"))?;
            return Ok(String::from_utf8_lossy(&output.stdout).into_owned());
        }
        Err(UNREACHABLE.to_string())
    }
}

