//! A small fuzzy matcher (subsequence matching with smart case and an
//! fzf-like scoring heuristic rewarding boundaries and consecutive matches).

pub struct FuzzyMatch {
    pub score: i64,
    pub indices: Vec<usize>,
}

const SCORE_MATCH: i64 = 16;
const GAP_START: i64 = -3;
const GAP_EXTENSION: i64 = -1;
const BONUS_BOUNDARY: i64 = 8;
const BONUS_CAMEL: i64 = 7;
const BONUS_CONSECUTIVE: i64 = 4;

fn bonus_at(text: &[char], j: usize) -> i64 {
    let cur = text[j];
    if j == 0 {
        return BONUS_BOUNDARY;
    }
    let prev = text[j - 1];
    if !prev.is_alphanumeric() {
        BONUS_BOUNDARY
    } else if prev.is_lowercase() && cur.is_uppercase() {
        BONUS_CAMEL
    } else if prev.is_alphabetic() && cur.is_numeric() {
        BONUS_CAMEL
    } else {
        0
    }
}

pub fn fuzzy_match(text: &str, pattern: &str) -> Option<FuzzyMatch> {
    if pattern.is_empty() {
        return Some(FuzzyMatch {
            score: 0,
            indices: Vec::new(),
        });
    }
    let case_sensitive = pattern.chars().any(|c| c.is_uppercase());
    let text_chars: Vec<char> = text.chars().collect();
    let pat_chars: Vec<char> = pattern.chars().collect();
    let n = text_chars.len();
    let m = pat_chars.len();
    if m > n {
        return None;
    }
    let eq = |a: char, b: char| -> bool {
        if case_sensitive {
            a == b
        } else {
            a.to_lowercase().eq(b.to_lowercase())
        }
    };

    // dp[i][j]: best score matching pattern[..=i] with pattern[i] at text[j]
    const NEG: i64 = i64::MIN / 4;
    let mut dp = vec![vec![NEG; n]; m];
    let mut back = vec![vec![usize::MAX; n]; m];
    for j in 0..n {
        if eq(text_chars[j], pat_chars[0]) {
            dp[0][j] = SCORE_MATCH + bonus_at(&text_chars, j) * 2;
        }
    }
    for i in 1..m {
        for j in i..n {
            if !eq(text_chars[j], pat_chars[i]) {
                continue;
            }
            let mut best = NEG;
            let mut best_k = usize::MAX;
            for k in (i - 1)..j {
                if dp[i - 1][k] == NEG {
                    continue;
                }
                let gap = j - k - 1;
                let mut s = dp[i - 1][k] + SCORE_MATCH;
                if gap == 0 {
                    s += bonus_at(&text_chars, j).max(BONUS_CONSECUTIVE);
                } else {
                    s += bonus_at(&text_chars, j);
                    s += GAP_START + GAP_EXTENSION * (gap as i64 - 1);
                }
                if s >= best {
                    best = s;
                    best_k = k;
                }
            }
            if best_k != usize::MAX {
                dp[i][j] = best;
                back[i][j] = best_k;
            }
        }
    }
    // pick the best end position (ties -> later position)
    let mut best = NEG;
    let mut best_j = usize::MAX;
    for j in 0..n {
        if dp[m - 1][j] != NEG && dp[m - 1][j] >= best {
            best = dp[m - 1][j];
            best_j = j;
        }
    }
    if best_j == usize::MAX {
        return None;
    }
    let mut indices = vec![0usize; m];
    let mut j = best_j;
    for i in (0..m).rev() {
        indices[i] = j;
        if i > 0 {
            j = back[i][j];
        }
    }
    Some(FuzzyMatch {
        score: best,
        indices,
    })
}
