new='''/// Wraps the tags spans into lines. Separators (`" | "`) move to a new line
/// when they don't fit (`current + width > max`), while tags move to a new
/// line when `current + width >= max`.
pub fn wrap_tag_spans<'a>(spans: Vec<(Span<'a>, bool)>, max_width: usize) -> Vec<Line<'a>> {
    let mut lines: Vec<Vec<Span<'a>>> = vec![Vec::new()];
    let mut current_width = 0usize;
    for (span, is_separator) in spans {
        let w = UnicodeWidthStr::width(span.content.as_ref());
        let overflow = if is_separator {
            current_width + w > max_width
        } else {
            current_width + w >= max_width
        };
        if overflow {
            lines.push(Vec::new());
            current_width = 0;
        }
        current_width += w;
        lines.last_mut().unwrap().push(span);
    }
    lines.into_iter().map(Line::from).collect()
}

