/// Renders a horizontal scrollbar on the last row of `area`.
pub fn render_horizontal_scrollbar(
    frame: &mut Frame,
    area: Rect,
    content_length: usize,
    position: usize,
    viewport_length: usize,
    style: Style,
) {
    if area.width < 2 || area.height == 0 {
        return;
    }
    let y = area.y + area.height - 1;
    let track_length = (area.width - 2) as usize;
    let buf = frame.buffer_mut();

    let set = |buf: &mut ratatui::buffer::Buffer, x: u16, sym: &str| {
        if let Some(cell) = buf.cell_mut((x, y)) {
            cell.set_symbol(sym);
            cell.set_style(style);
        }
    };

    set(buf, area.x, "◄");
    set(buf, area.x + area.width - 1, "►");

    if track_length == 0 {
        return;
    }

    let viewport_length = if viewport_length == 0 {
        area.width as usize
    } else {
        viewport_length
    };
    let max_position = content_length.saturating_sub(1);
    let start_position = position.min(max_position);
    let max_viewport_position = max_position + viewport_length;
    let end_position = start_position + viewport_length;

    let rounding_divide = |n: usize, d: usize| -> usize {
        if d == 0 {
            0
        } else {
            (n + d / 2) / d
        }
    };

    let thumb_start = rounding_divide(start_position * track_length, max_viewport_position);
    let thumb_end = rounding_divide(end_position * track_length, max_viewport_position);
    let thumb_start = thumb_start.min(track_length.saturating_sub(1));
    let thumb_end = thumb_end.clamp(thumb_start + 1, track_length);

    for i in 0..track_length {
        let x = area.x + 1 + i as u16;
        if i >= thumb_start && i < thumb_end {
            set(buf, x, "🬋");
        } else {
            set(buf, x, "─");
        }
    }
}
